export const ProjectsScreen: React.FC<ProjectsScreenProps> = ({ onClose }) => {
    const [activeCategory, setActiveCategory] = useState<ProjectCategory>('ALL');
    const [selectedId, setSelectedId] = useState(14); 
    const [isClosing, setIsClosing] = useState(false);

    const filteredProjects = useMemo(() => {
        if (activeCategory === 'ALL') return PROJECTS;
        return PROJECTS.filter(p => p.category === activeCategory);
    }, [activeCategory]);

    useEffect(() => {
        if (!filteredProjects.find(p => p.id === selectedId) && filteredProjects.length > 0) {
            setSelectedId(filteredProjects[0].id);
        }
    }, [filteredProjects, selectedId]);

    const handleClose = () => {
        sfx.play('CLICK');
        setIsClosing(true);
        setTimeout(onClose, 300);
    };

    const handleCategoryChange = (cat: ProjectCategory) => {
        sfx.play('CLICK');
        setActiveCategory(cat);
    }

    const handleLaunch = (url?: string) => {
        if (!url) return;
        sfx.play('CLICK');
        window.open(url, '_blank', 'noopener,noreferrer');
    }

    const activeProject = PROJECTS.find(p => p.id === selectedId) || PROJECTS[0];

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-[#050505] overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
