                        style={{ clipPath: 'polygon(0 0, 100% 0, 85% 100%, 0 100%)' }}
                    >
                        <div className="flex items-center gap-2 pr-4">
                            <Icons.Close className="w-5 h-5 transition-transform group-hover:rotate-90" />
