import React, { useState } from 'react';
import { sfx } from '../../utils/SoundManager';
import { Icons } from '../StackScreen/assets/Icons';
import { useImageInteraction } from '../InteractionSystem';

interface ContactScreenProps {
    onClose: () => void;
}

const SOCIAL_LINKS = [
    { id: 'codepen', name: 'CODEPEN', url: 'https://codepen.io/', user: '@unibelands', color: '#F2D019' },
    { id: 'instagram', name: 'INSTAGRAM', url: 'https://instagram.com/', user: '@unibelands', color: '#f472b6' },
    { id: 'facebook', name: 'FACEBOOK', url: 'https://facebook.com/', user: 'unibelands.dev', color: '#38bdf8' },
    { id: 'linkedin', name: 'LINKEDIN', url: 'https://linkedin.com/', user: 'Daniel Unibe', color: '#c084fc' },
    { id: 'dribbble', name: 'DRIBBBLE', url: 'https://dribbble.com/', user: 'unibelands', color: '#fb923c' },
];

const EMAIL_ADDRESS = "contact@unibelands.com";

export const ContactScreen: React.FC<ContactScreenProps> = ({ onClose }) => {
    const [isClosing, setIsClosing] = useState(false);

    const handleClose = () => {
        sfx.play('CLICK');
        setIsClosing(true);
        setTimeout(onClose, 300);
    };

    const handleCopyEmail = () => {
        navigator.clipboard.writeText(EMAIL_ADDRESS);
        sfx.play('EQUIP');
        // El sistema de InteractionUI ya escucha el toast si quisiéramos, 
        // pero aquí forzaremos un mensaje descriptivo si estuviera disponible el contexto.
    };

    return (
        <div className={`
            fixed inset-0 z-[300] flex flex-col items-center
