import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { ASSETS } from '../../config/assets';
import { Ticker } from '../../utils/GlobalTicker';

interface ThreeSkyProps {
    scrollRef: React.MutableRefObject<number>;
}

export const ThreeSky: React.FC<ThreeSkyProps> = React.memo(({ scrollRef }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        // --- SETUP ---
        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        const scene = new THREE.Scene();

        // Orthographic camera for pixel-perfect 2D control in 3D space
        const frustumSize = 1000;
        const aspect = w / h;
        const camera = new THREE.OrthographicCamera(
            frustumSize * aspect / -2,
            frustumSize * aspect / 2,
            frustumSize / 2,
            frustumSize / -2,
            1,
            2000
        );
        camera.position.z = 1000;

        const renderer = new THREE.WebGLRenderer({ 
            alpha: true, 
            antialias: false, 
            powerPreference: "high-performance",
            depth: false,
            stencil: false
        });

        renderer.setSize(w, h);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.domElement.style.position = 'absolute';
        renderer.domElement.style.inset = '0';
        renderer.domElement.style.pointerEvents = 'none';
        containerRef.current.appendChild(renderer.domElement);

        // --- CLOUD CONFIGURATION ---
        // Reduced count and adjusted geometry for a more "breathable" sky
        const CLOUD_COUNT = 18; // Reduced from 35 to allow sky visibility
        const dummy = new THREE.Object3D();
        const geometry = new THREE.PlaneGeometry(400, 220); // Slightly more horizontal aspect

        const loader = new THREE.TextureLoader();
        const texture = loader.load(ASSETS.CLOUDS[0]); 

        const material = new THREE.MeshBasicMaterial({
            map: texture,
            transparent: true,
            opacity: 0.8,
            depthWrite: false,
        });

        const mesh = new THREE.InstancedMesh(geometry, material, CLOUD_COUNT);
        mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        scene.add(mesh);

        // --- INITIALIZE CLOUD DATA ---
        const cloudData: { x: number; y: number; z: number; scale: number; speed: number; parallax: number; opacity: number }[] = [];

        const getSceneWidth = () => 1000 * (containerRef.current?.clientWidth || 1000) / (containerRef.current?.clientHeight || 1000);

        for (let i = 0; i < CLOUD_COUNT; i++) {
            const sceneW = getSceneWidth();
            const rangeX = sceneW * 3.5;

            // Layers: 0 (Back/Small), 1 (Mid), 2 (Front/Larger)
            const layer = i % 3;

            let z = 0, speed = 0, parallax = 0, opacity = 1, scale = 1, y = 0;

            if (layer === 0) {
                // Background Layer: High up, small, slow, transparent
                z = -200; 
                y = (Math.random() * 300) + 150;
                scale = 1.2 + Math.random() * 0.8; // Reduced scale significantly
                opacity = 0.2 + Math.random() * 0.2;
                speed = 0.1; 
                parallax = 0.04;
            } else if (layer === 1) {
                // Mid Layer
                z = -50; 
                y = (Math.random() * 250) + 100;
                scale = 1.0 + Math.random() * 0.6;
                opacity = 0.5 + Math.random() * 0.2;
                speed = 0.2; 
                parallax = 0.15;
            } else {
                // Front Layer: Closer, but still contained size
                z = 100; 
                y = (Math.random() * 300) + 50;
                scale = 0.8 + Math.random() * 0.5; // Keeps them from blocking the view
                opacity = 0.7 + Math.random() * 0.15;
                speed = 0.35; 
                parallax = 0.3;
            }

            cloudData.push({
                x: (Math.random() * rangeX) - (rangeX / 2),
                y, z, scale, speed, parallax, opacity
            });

            // Color variation for depth
            const gray = 0.9 + (layer * 0.05); 
            mesh.setColorAt(i, new THREE.Color(gray, gray, gray));
        }

        // --- ANIMATION LOOP (SYNCED) ---
        const tick = () => {
            if (!containerRef.current) return;

            const currentW = containerRef.current.clientWidth;
            const currentH = containerRef.current.clientHeight || 1;
            const currentAspect = currentW / currentH;
            const sceneVisibleWidth = 1000 * currentAspect;
            const pixelToUnitRatio = sceneVisibleWidth / (currentW || 1);
            const respawnLimit = sceneVisibleWidth * 2.0;
            const scrollX = scrollRef.current;

            for (let i = 0; i < CLOUD_COUNT; i++) {
                const data = cloudData[i];

                // 1. Move constantly (Wind)
                data.x -= data.speed;

                // 2. Parallax Calculation
                const parallaxOffset = (scrollX - window.innerWidth) * pixelToUnitRatio * data.parallax;
                let displayX = data.x - parallaxOffset;

                // 3. Wrapping Logic
                if (displayX < -respawnLimit) {
                    data.x += (respawnLimit * 2);
                    displayX = data.x - parallaxOffset;
                } else if (displayX > respawnLimit) {
                    data.x -= (respawnLimit * 2);
                    displayX = data.x - parallaxOffset;
                }

                // 4. Update Matrix
                dummy.position.set(displayX, data.y, data.z);
                dummy.scale.set(data.scale, data.scale, 1);
                dummy.updateMatrix();
                mesh.setMatrixAt(i, dummy.matrix);
            }

            mesh.instanceMatrix.needsUpdate = true;
            renderer.render(scene, camera);
        };

        // Subscribe to Global Ticker
        Ticker.add(tick);

        // --- RESIZE HANDLER ---
        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            const newAspect = newW / newH;
            camera.left = -frustumSize * newAspect / 2;
            camera.right = frustumSize * newAspect / 2;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            Ticker.remove(tick);
            window.removeEventListener('resize', handleResize);
            if (containerRef.current && renderer.domElement) {
                containerRef.current.removeChild(renderer.domElement);
            }
            // Memory Cleanup
            geometry.dispose();
            material.dispose();
            texture.dispose();
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            className="w-full h-full relative overflow-hidden" 
            style={{ 
                background: 'linear-gradient(180deg, #1E90FF 0%, #87CEFA 100%)', 
                zIndex: 0 
            }}
        >
            <div 
                className="absolute inset-0 w-full h-full pointer-events-none"
                style={{
                    background: 'linear-gradient(to bottom, transparent 0%, rgba(200, 225, 255, 0) 50%, rgba(255, 255, 255, 0.5) 80%, #FFFFFF 100%)',
                    zIndex: 0
                }}
            />
        </div>
    );
});

