                    100% { 
                        opacity: 1;
                        transform: translateZ(0px) scale(1);
                        filter: blur(0px);
                        letter-spacing: 0;
                    }
                }

                @keyframes holo-float {
                    0%, 100% { transform: translateY(0) translateZ(0); text-shadow: -2px 0 rgba(0,255,255,0.5), 2px 0 rgba(255,0,0,0.5); }
                    50% { transform: translateY(-5px) translateZ(10px); text-shadow: 2px 0 rgba(0,255,255,0.5), -2px 0 rgba(255,0,0,0.5); }
                }

                @keyframes banner-reveal {
                    0% { transform: scaleX(0); opacity: 0; }
                    100% { transform: scaleX(1); opacity: 1; }
                }

                @keyframes element-pop {
                    0% { transform: scale(0.8) translateY(30px); opacity: 0; }
                    100% { transform: scale(1) translateY(0); opacity: 1; }
                }

                @keyframes holo-flicker {
                    0%, 100% { opacity: 1; }
                    33% { opacity: 0.85; }
                    66% { opacity: 0.95; }
                }

                @keyframes hazard-scroll { 
                    0% { background-position: 0 0; } 
                    100% { background-position: 28px 0; } 
                }

                /* =========================================
                   STRUCTURE
                   ========================================= */
                .scene {
                    width: 100%; height: 100%; position: relative;
                    display: flex; justify-content: center; align-items: center;
                    transform-style: preserve-3d; /* Permite que los hijos 3D funcionen */
                }

                .card {
                    position: absolute; width: 85%; height: 85%; top: 50%; left: 50%; transform: translate(-50%, -50%);
                    background: radial-gradient(circle at center, rgba(15, 45, 55, 0.5) 0%, rgba(5, 15, 20, 0.98) 100%);
                    backdrop-filter: blur(10px); border: 1.5px solid rgba(45, 212, 191, 0.6); border-radius: 1.5cqw;
                    z-index: 10; overflow: hidden;
                    box-shadow: inset 0 0 60px rgba(45, 212, 191, 0.15), 0 0 40px rgba(0, 0, 0, 0.7);
                    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
                }

                .grid-hex { 
                    inset: 0; position: absolute; 
                    background-image: var(--svg-hex); 
                    background-size: 24px 42px; 
                    opacity: 0.3;
                    mask-image: radial-gradient(circle at center, black 50%, transparent 100%);
                    -webkit-mask-image: radial-gradient(circle at center, black 50%, transparent 100%);
                    transition: opacity 0.4s ease;
                }

                .card::after {
                    content: ""; position: absolute; inset: 0;
                    background: repeating-linear-gradient(rgba(0,0,0,0) 0, rgba(0,0,0,0.1) 2px, rgba(0,0,0,0) 4px);
                    pointer-events: none; z-index: 100;
                }

                .laser {
                    position: absolute; left: 0; width: 100%; height: 1.2cqw;
                    background: var(--c-a-teal); box-shadow: 0 0 3cqw var(--c-a-teal), 0 0 6cqw var(--c-a-teal);
                    z-index: 40; opacity: 0;
                }
                .laser.active { animation: laser-scan 0.8s ease-in-out forwards; }

                .img {
                    position: absolute; top: 55%; left: 50%; transform: translate(-50%, -50%);
                    height: 100%; width: auto; z-index: 20;
                    pointer-events: none;
                    opacity: 0.7; animation: holo-flicker 4s infinite;
                    object-fit: contain;
                    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
                }

                .ui-echo {
                    position: absolute; width: 85%; height: 85%;
                    top: 50%; left: 50%; transform: translate(-50%, -50%);
                    z-index: 30;
                    display: flex; flex-direction: column; align-items: center; 
                    padding: 0; box-sizing: border-box; 
                    transform-style: preserve-3d;
                    perspective: 500px;
                }

                /* =========================================
                   HOVER INTERACTIONS
                   ========================================= */
                .scene:hover .card {
                    box-shadow: inset 0 0 80px rgba(45, 212, 191, 0.4), 0 0 60px rgba(45, 212, 191, 0.6);
                    border-color: rgba(45, 212, 191, 1);
                }

                .scene:hover .img {
                    opacity: 1;
                    filter: brightness(1.2) contrast(1.1);
                    transform: translate(-50%, -50%) scale(1.05);
                }

                .scene:hover .grid-hex {
                    opacity: 0.6;
                }

                /* Al hacer hover, el texto se "sale" más hacia el usuario */
                .scene:hover .line-uiux, 
                .scene:hover .line-designer {
                    transform: translateZ(60px);
                    text-shadow: -3px 0 rgba(0,255,255,0.8), 3px 0 rgba(255,0,0,0.8);
                }

                /* =========================================
                   TITLES (HOLOGRAPHIC)
                   ========================================= */
                .txt-container {
                    display: flex; flex-direction: column; align-items: center;
                    margin-top: 0; width: 100%; 
                    opacity: 0; 
                    transform-style: preserve-3d;
                    /* La rotación inicial se elimina para que sea pura proyección frontal */
                }

                .txt-container.active { 
                    opacity: 1;
                    /* Ya no animamos el contenedor completo con rotación, animamos los hijos o usamos una animación de entrada más simple */
                }

                .line-title {
                    font-family: 'Anton', sans-serif; text-transform: uppercase; line-height: 0.85;
                    -webkit-text-stroke: 1cqw #000; paint-order: stroke fill; text-align: center;
                    white-space: nowrap; filter: drop-shadow(1cqw 1cqw 0 #000);
                    /* Configuración Holograma */
                    opacity: 0;
                    transform-origin: center center;
                    backface-visibility: hidden;
                    transition: transform 0.3s ease-out, text-shadow 0.3s ease;
                }

                /* Animación individual para que crezcan hacia afuera */
                .txt-container.active .line-uiux {
                    animation: holo-projection 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards, holo-float 4s ease-in-out infinite 0.8s;
                }

                .txt-container.active .line-designer {
                    animation: holo-projection 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards 0.2s, holo-float 5s ease-in-out infinite 1s;
                }

                .line-uiux { 
                    font-size: 16cqw; color: var(--c-h-yel); 
                    text-shadow: 0 0 25px rgba(250, 204, 21, 0.5);
                }

                .line-designer {
                    font-size: 10cqw; color: #fff; margin-top: 1cqw;
                    padding: 0.8cqw 8cqw; background: #000;
                    box-shadow: 1.2cqw 1.2cqw 0 var(--c-b-red);
                    border: 1px solid rgba(255,255,255,0.2);
                }

                .status-banner {
                    width: 75%; background: var(--c-h-yel); height: 8.5cqw; 
                    display: flex; align-items: center; justify-content: center;
                    border: 0.5cqw solid #000; box-shadow: 0.8cqw 0.8cqw 0 #000;
                    margin-top: 4cqw; position: relative; overflow: hidden; opacity: 0;
                    transform: translateZ(20px); /* El banner flota un poco por defecto */
                }
                .status-banner.active { animation: banner-reveal 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }

                .hazard-bar {
                    position: absolute; left: 0; width: 6cqw; height: 100%;
                    background: var(--hazard); background-size: 28px 100%; 
                    border-right: 0.4cqw solid #000; animation: hazard-scroll 1s linear infinite;
                }
                .status-text {
                    font-family: 'Anton', sans-serif; color: #000; font-size: 3cqw; 
                    text-align: center; z-index: 5; padding: 0 10cqw; line-height: 1; 
                    letter-spacing: 0.1cqw; width: 100%; box-sizing: border-box;
                }

                /* =========================================
                   PARAGRAPH
                   ========================================= */
                .data-paragraph-container {
                    width: 65%; padding: 2cqw; box-sizing: border-box;
                    background: linear-gradient(to right, transparent, rgba(45,212,191,0.08), transparent);
                    border-top: 1.5px solid rgba(45, 212, 191, 0.4);
                    border-bottom: 1.5px solid rgba(45, 212, 191, 0.4);
                    margin-top: 3.5cqw; opacity: 0;
                    transform: translateZ(0); /* Se mantiene plano en la tarjeta */
                }
                .data-paragraph-container.active { animation: element-pop 0.8s ease-out forwards; }

                .data-paragraph {
                    font-family: 'Roboto Condensed', sans-serif; font-weight: 700; color: #fff; 
                    font-size: 2.2cqw; text-transform: uppercase; line-height: 1.4; 
                    text-shadow: 0 0 10px rgba(0,0,0,1); text-align: center; margin: 0;
                    letter-spacing: 0.05cqw;
                }

                /* =========================================
                   STATS GRID
                   ========================================= */
                .stats-grid {
                    position: absolute; 
                    bottom: 22cqw; 
                    width: 48%; 
                    display: grid; 
                    grid-template-columns: repeat(2, 1fr); 
                    gap: 1.5cqw;
                    opacity: 0; 
                    z-index: 60;
                }
                .stats-grid.active { animation: element-pop 0.7s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }

                .stat-box {
                    background: rgba(10, 25, 30, 0.98);
                    border: 0.35cqw solid var(--c-a-teal);
                    aspect-ratio: 1 / 1; 
                    display: flex; 
                    flex-direction: column; 
                    justify-content: center; 
                    align-items: center; 
                    padding: 1cqw;
                    clip-path: polygon(15% 0, 100% 0, 100% 85%, 85% 100%, 0 100%, 0 15%);
                    box-shadow: 0.6cqw 0.6cqw 0 rgba(45, 212, 191, 0.4);
                    position: relative;
                }

                .stat-box::before {
                    content: ""; position: absolute; inset: 0;
                    background: linear-gradient(135deg, rgba(45, 212, 191, 0.2) 0%, transparent 100%);
                }

                .stat-label {
                    font-family: 'Share Tech Mono', monospace; 
                    font-size: 1.8cqw; 
                    color: var(--c-a-teal);
                    text-transform: uppercase; 
                    margin-bottom: 0.2cqw; 
                    z-index: 2;
                }
                .stat-value {
                    font-family: 'Anton', sans-serif; 
                    font-size: 3.5cqw; 
                    color: #fff;
                    line-height: 1; 
                    text-shadow: 0 0 10px rgba(45, 212, 191, 0.6); 
                    z-index: 2;
                }
            `}</style>

            <div className="scene">
                <div className="card">
                    <div className="grid-hex"></div>
                    <div className={`laser ${step >= 1 ? 'active' : ''}`}></div>
                </div>

                <img src="https://i.imgur.com/UlHz9On.png" alt="Vault Hunter" className="img" />

                <div className="ui-echo">
                    {/* BLOQUE SUPERIOR */}
                    <div className={`txt-container ${step >= 2 ? 'active' : ''}`}>
                        <div className="line-title line-uiux">UI/UX</div>
                        <div className="line-title line-designer">GAME DESIGNER</div>

                        <div className={`status-banner ${step >= 3 ? 'active' : ''}`}>
                            <div className="hazard-bar"></div>
                            <div className="status-text">INTELLIGENCE SYSTEMS</div>
                            <div className="hazard-bar" style={{left: 'auto', right: 0, borderRight: 'none', borderLeft: '0.4cqw solid #000'}}></div>
                        </div>
                    </div>

                    {/* DESCRIPCIÓN CENTRAL */}
                    <div className={`data-paragraph-container ${step >= 4 ? 'active' : ''}`}>
                        <p className="data-paragraph">
                            OPTIMIZO ECOSISTEMAS DIGITALES MEDIANTE LA CONVERGENCIA DE INTELIGENCIA ARTIFICIAL Y DINÁMICAS LÚDICAS DE ALTA FIDELIDAD.
                        </p>
                    </div>

                    {/* GRID DE ESTADÍSTICAS */}
                    <div className={`stats-grid ${step >= 5 ? 'active' : ''}`}>
                        <div className="stat-box">
                            <span className="stat-label">EXP</span>
                            <span className="stat-value">99</span>
                        </div>
                        <div className="stat-box">
                            <span className="stat-label">LVL</span>
                            <span className="stat-value">32</span>
                        </div>
                        <div className="stat-box">
                            <span className="stat-label">RAR</span>
                            <span className="stat-value">LEG</span>
                        </div>
                        <div className="stat-box">
                            <span className="stat-label">STR</span>
                            <span className="stat-value">MAX</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

