// --- WEST ZONE ---
interface WestZoneProps {
    onMapClick: () => void;
}

export const WestZone: React.FC<WestZoneProps> = React.memo(({ onMapClick }) => {
    // Interacciones de las estructuras de fondo
    const propsA = useImageInteraction("WEST SECTOR: OUTPOST", ASSETS.STRUCTURES.WEST_A);
    const propsB = useImageInteraction("WEST SECTOR: SILO", ASSETS.STRUCTURES.WEST_B);

    // URL de la interfaz táctica
    const TACTICAL_INTERFACE_URL = "https://i.imgur.com/3xc56Nd.png";

    const handleInteraction = (e: React.MouseEvent) => {
        e.stopPropagation();
        onMapClick();
    };

    return (
        <>
            {/* ESTRUCTURAS DE FONDO (WEST_A) */}
            <div className="absolute left-0 top-0 h-full w-[100vw] z-0">
                <div className="absolute inset-0 flex items-end justify-start">
                    <img 
                        src={ASSETS.STRUCTURES.WEST_A} 
                        alt="Estructura Oeste A" 
                        {...propsA}
                        className={`h-full w-auto object-contain object-bottom select-none ${propsA.className}`}
                        draggable="false"
                        decoding="async"
                        style={{
                            transform: 'translate(-155px, 195px) scale(2.16)',
                            transformOrigin: 'bottom left',
                            filter: 'blur(0.5px) contrast(1.1)' 
                        }}
                    />
                </div>
            </div>

            {/* TACTICAL DISPLAY LAYER - Pegada al lateral izquierdo - BAJADA ADICIONAL (-480px) */}
            <div className="absolute z-[100] flex items-end justify-start pointer-events-auto cursor-pointer"
                 onClick={handleInteraction}
                 style={{
                     left: '0px', 
                     bottom: '-480px',
                     transform: 'none',
                     transformOrigin: 'left top'
                 }}>
                <img 
                    src={TACTICAL_INTERFACE_URL} 
                    alt="TACTICAL INTERFACE" 
                    className="relative z-10 w-[625px] object-contain select-none" 
                    style={{ 
                        maskImage: 'none',
                        WebkitMaskImage: 'none'
                    }}
                />
            </div>

            {/* WEST SILO (B) - Z-INDEX 50 */}
            <div className="absolute left-0 top-0 h-full w-[100vw] flex items-end justify-start z-50">
                <img 
                    src={ASSETS.STRUCTURES.WEST_B} 
                    alt="Estructura Oeste B" 
                    {...propsB}
                    className={`h-full w-auto object-contain object-bottom select-none ${propsB.className}`}
                    style={{ transform: 'translate(430px, 245px) scale(2.98)', transformOrigin: 'bottom left' }}
                />
            </div>
        </>
    );
});

// --- NORTH ZONE ---
interface NorthZoneProps {
    onQuestClick: () => void;
    activeIndex: number;
    triggerAnimation: boolean;
}

export const NorthZone: React.FC<NorthZoneProps> = React.memo(({ onQuestClick, activeIndex, triggerAnimation }) => {
    const propsRuins = useImageInteraction("NORTH SECTOR: RUINS", ASSETS.STRUCTURES.STONE_MOUNDS);
    const propsBg = useImageInteraction("EAST SECTOR: GATEWAY", ASSETS.BG.TRANSITION);
    const propsBase = useImageInteraction("EAST SECTOR: FOUNDATION", ASSETS.STRUCTURES.TRANSITION_BASE);
    const propsPropp = useImageInteraction("QUEST GIVER", ASSETS.PROPS.PROPP);

    return (
        <>
            <div className="absolute left-[100vw] bottom-0 z-[51] flex items-end justify-center pointer-events-none">
                <img 
                    src={ASSETS.STRUCTURES.STONE_MOUNDS} 
                    alt="Stone Mounds" 
                    {...propsRuins}
                    className={`object-contain object-bottom select-none ${propsRuins.className}`}
                    style={{ height: '85vh', transform: 'translateX(-50%) translateY(20vh)', maxWidth: 'none', filter: 'brightness(0.9)' }}
                />
            </div>

            {/* ECHO PORTAL (Backdrop) - Positioned BEHIND Quest Giver */}
            <div 
                className="absolute left-[150vw] bottom-0 z-[90] flex items-end justify-center pointer-events-none"
                style={{ 
                    // Adjusted placement: Moved 150px DOWN from previous position
                    // Previous Y: 10vh + 180px -> New Y: 10vh + 330px
                    // X remains at -310px offset
                    transform: 'translateX(calc(-50% - 310px)) translateY(calc(10vh + 330px))', 
                }}
            >
                <EchoPortal trigger={triggerAnimation} />
            </div>

            {/* QUEST GIVER (PROPP) - Z-Index 100 to sit in front */}
            <div className="absolute left-[150vw] bottom-0 z-[100] flex items-end justify-center pointer-events-auto cursor-pointer group"
                 onClick={onQuestClick}
                 onMouseEnter={propsPropp.onMouseEnter}
                 onMouseLeave={propsPropp.onMouseLeave}
                 style={{ 
                     transform: 'translateX(calc(-50% - 410px)) translateY(calc(10vh + 455px))',
                 }}
            >
                <CastShadow
                    shadowSrc={ASSETS.PROPS.PROPP}
                    debugId="PROPP"
                    height="40vh"
                    initialConfig={{ perspective: 1140, rotateX: 44, skewX: -9, scaleY: 1.33, x: -20, y: 14, blur: 1.5, opacity: 0.8 }}
                >
                    <div className="relative">
                        <img 
                            src={ASSETS.PROPS.PROPP} 
                            alt="QUEST GIVER" 
                            className={`object-contain object-bottom select-none brightness-100 ${propsPropp.className}`}
                            style={{ height: '40vh' }} 
                        />
                    </div>
                </CastShadow>
                <WorldTooltip title="QUESTS" subtitle="PROJECT LOG" side="right" className="!bottom-[90%]" />
            </div>

            <div className="absolute left-[180vw] bottom-0 z-[44] flex items-end justify-center pointer-events-none">
                <img 
                    src={ASSETS.BG.TRANSITION} 
                    alt="Estructura Transición" 
                    {...propsBg}
                    className={`object-contain object-bottom select-none opacity-90 ${propsBg.className}`}
                    style={{
                        height: '70vh', 
                        transform: 'translateX(calc(-50% + 100px)) translateY(100px)', 
                        maxWidth: 'none',
                        filter: 'brightness(0.7) contrast(1.2)'
                    }}
                />
            </div>

            <div className="absolute left-[180vw] bottom-0 z-[46] flex items-end justify-center pointer-events-none">
                <img 
                    src={ASSETS.STRUCTURES.TRANSITION_BASE} 
                    alt="Estructura Base Norte-Este" 
                    {...propsBase}
                    className={`object-contain object-bottom select-none ${propsBase.className}`}
                    style={{
                        height: '60vh', 
                        transform: 'translateX(calc(-50% + 400px)) translateY(200px)', 
                        maxWidth: 'none',
                        filter: 'brightness(0.8) contrast(1.3)' 
                    }}
                />
            </div>
        </>
    );
});

