:root {
    /* Color Palette */
    --yellow: #facc15;
    --teal: #2DD4BF;
    --red: #ef4444;

    /* Effects & Patterns */
    --hazard-gradient: repeating-linear-gradient(-45deg, #000, #000 10px, var(--yellow) 10px, var(--yellow) 20px);
    --hex-svg: url("data:image/svg+xml,%3Csvg width='56' height='100' viewBox='0 0 56 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M28 66L0 50L0 16L28 0L56 16L56 50L28 66L28 100' fill='none' stroke='%232DD4BF' stroke-width='1.5' stroke-opacity='0.5'/%3E%3Cpath d='M28 0L28 33' fill='none' stroke='%2300FFF0' stroke-width='1' stroke-opacity='0.4'/%3E%3C/svg%3E");

    /* Layout Tokens */
    --card-inset: 7.5%;
    --transition-snappy: cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --transition-bouncy: cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* Reset & Base */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background: #000 url("https://plus.unsplash.com/premium_photo-1673329271082-365e038a1efd?q=80&w=1470&auto=format&fit=crop") center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100vh;
    overflow: hidden;
}

/* --- Core Animations --- */
@keyframes laser-scan {
    0% {
        top: 0%;
        opacity: 0;
    }

    20%,
    80% {
        opacity: 1;
    }

    100% {
        top: 100%;
        opacity: 0;
    }
}

@keyframes shine-reflect {

    0%,
    90% {
        background-position: -200% 0;
    }

    100% {
        background-position: 200% 0;
    }
}

@keyframes atlas-unfold {
    0% {
        transform: scale(0.2) rotateY(90deg);
        filter: brightness(10) blur(20px);
        opacity: 0;
    }

    60% {
        transform: scale(1.6) rotateY(-5deg);
        filter: brightness(2) blur(2px);
        opacity: 1;
    }

    100% {
        transform: scale(1.5) rotateY(0deg);
        filter: brightness(1.1);
        opacity: 1;
    }
}

@keyframes banner-reveal {
    from {
        transform: scaleX(0);
        opacity: 0;
    }

    to {
        transform: scaleX(1);
        opacity: 1;
    }
}

@keyframes element-pop {
    from {
        transform: scale(0.8) translateY(30px);
        opacity: 0;
    }

    to {
        transform: scale(1) translateY(0);
        opacity: 1;
    }
}

@keyframes holo-flicker {

    0%,
    100% {
        opacity: 0.9;
    }

    33% {
        opacity: 0.85;
    }

    66% {
        opacity: 0.95;
    }
}

@keyframes hazard-scroll {
    to {
        background-position: 28px 0;
    }
}

/* === HOLOGRAM EMERGE ANIMATION === */
@keyframes hologram-emerge {
    0% {
        transform: translateZ(0) scale(1);
        filter: brightness(1);
    }

    50% {
        transform: translateZ(60px) scale(1.08);
        filter: brightness(1.3) drop-shadow(0 0 30px rgba(45, 212, 191, 0.6));
    }

    100% {
        transform: translateZ(40px) scale(1.05);
        filter: brightness(1.15) drop-shadow(0 0 20px rgba(45, 212, 191, 0.4));
    }
}

@keyframes hologram-glow {

    0%,
    100% {
        text-shadow: 0 0 10px currentColor, 0 0 20px currentColor, 0 0 40px rgba(45, 212, 191, 0.5);
    }

    50% {
        text-shadow: 0 0 20px currentColor, 0 0 40px currentColor, 0 0 80px rgba(45, 212, 191, 0.8), 0 0 120px rgba(45, 212, 191, 0.4);
    }
}

@keyframes hologram-scanline {
    0% {
        background-position: 0 -100%;
    }

    100% {
        background-position: 0 200%;
    }
}

@keyframes hex-drift {
    0% {
        background-position: 0 0;
    }

    100% {
        background-position: 56px 100px;
    }
}

@keyframes hex-drift-reverse {
    0% {
        background-position: 56px 100px;
    }

    100% {
        background-position: 0 0;
    }
}

@keyframes hex-color-cycle {

    0%,
    100% {
        filter: hue-rotate(0deg) brightness(1);
    }

    20% {
        filter: hue-rotate(45deg) brightness(1.2);
    }

    40% {
        filter: hue-rotate(90deg) brightness(1.1);
    }

    60% {
        filter: hue-rotate(180deg) brightness(1.3);
    }

    80% {
        filter: hue-rotate(270deg) brightness(1.15);
    }
}

/* === PREMIUM HOVER ANIMATIONS === */
@keyframes border-glow-pulse {

    0%,
    100% {
        box-shadow:
            0 20px 40px rgba(0, 0, 0, 0.8),
            0 0 30px rgba(250, 204, 21, 0.3),
            inset 0 0 20px rgba(250, 204, 21, 0.05);
    }

    50% {
        box-shadow:
            0 25px 50px rgba(0, 0, 0, 0.9),
            0 0 50px rgba(250, 204, 21, 0.5),
            0 0 80px rgba(250, 204, 21, 0.2),
            inset 0 0 30px rgba(250, 204, 21, 0.1);
    }
}

@keyframes scanline-sweep {
    0% {
        top: -2px;
        opacity: 0;
    }

    10% {
        opacity: 1;
    }

    90% {
        opacity: 1;
    }

    100% {
        top: calc(100% + 2px);
        opacity: 0;
    }
}

@keyframes shimmer-effect {
    0% {
        background-position: -200% 0;
    }

    100% {
        background-position: 200% 0;
    }
}

@keyframes value-glow {

    0%,
    100% {
        text-shadow: 0 0 30px rgba(45, 212, 191, 0.6);
    }

    50% {
        text-shadow: 0 0 50px rgba(45, 212, 191, 1), 0 0 80px rgba(45, 212, 191, 0.5);
    }
}

@keyframes tag-bounce {

    0%,
    100% {
        transform: translateY(0) scaleX(1);
    }

    25% {
        transform: translateY(-4px) scaleX(1.1);
    }

    50% {
        transform: translateY(-2px) scaleX(1.05);
    }
}

@keyframes energy-ring {
    0% {
        transform: scale(0.95);
        opacity: 0.5;
    }

    50% {
        transform: scale(1.02);
        opacity: 0.8;
    }

    100% {
        transform: scale(0.95);
        opacity: 0.5;
    }
}

/* --- Layout Structure --- */
.scene {
    width: 533px;
    height: 800px;
    min-width: 533px;
    min-height: 800px;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    container-type: size;
    perspective: 1200px;
}

.card {
    position: absolute;
    inset: var(--card-inset);
    background: radial-gradient(circle at center, rgba(15, 45, 55, 0.5) 0%, rgba(5, 15, 20, 0.98) 100%);
    backdrop-filter: blur(10px);
    border: 1.5px solid rgba(45, 212, 191, 0.6);
    border-radius: 1.5cqw;
    z-index: 10;
    overflow: hidden;
    box-shadow: inset 0 0 60px rgba(45, 212, 191, 0.15), 0 0 40px rgba(0, 0, 0, 0.7);
}

.card::before {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--hex-svg) 0 0 / 28px 50px;
    opacity: 0.7;
    mask-image: radial-gradient(circle at center, black 70%, transparent 100%);
    animation:
        hex-drift 8s linear infinite,
        hex-color-cycle 12s ease-in-out infinite;
}

/* Segunda capa de hexágonos - movimiento opuesto para profundidad */
.card::after {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--hex-svg) 14px 25px / 35px 62px;
    opacity: 0.35;
    mask-image: radial-gradient(circle at center, black 50%, transparent 90%);
    animation:
        hex-drift-reverse 12s linear infinite,
        hex-color-cycle 8s ease-in-out infinite reverse;
    mix-blend-mode: screen;
    pointer-events: none;
}

.laser {
    position: absolute;
    inset: 0 0 auto 0;
    height: 1.2cqw;
    background: var(--teal);
    box-shadow: 0 0 3cqw var(--teal), 0 0 6cqw var(--teal);
    z-index: 40;
    opacity: 0;
}

.laser.active {
    animation: laser-scan 0.8s ease-in-out forwards;
}

/* --- Visual Elements --- */
.hologram-wrapper {
    position: absolute;
    top: 52%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 60%;
    height: 105%;
    z-index: 15;
    pointer-events: none;
    animation: holo-flicker 4s infinite;
    display: flex;
    justify-content: center;
    align-items: center;
}

.hologram-wrapper::after {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--hex-svg) 0 0 / 14px 24px;
    opacity: 0.5;
    mask-image: linear-gradient(to bottom, transparent, black 10%, black 90%, transparent);
    mix-blend-mode: overlay;
    pointer-events: none;
}

.img {
    height: 100%;
    width: auto;
    filter: drop-shadow(0 0 20px #000);
}

/* --- UI Systems --- */
.ui-echo {
    position: absolute;
    inset: var(--card-inset);
    z-index: 30;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 2cqw 0 12cqw;
    transform-style: preserve-3d;
}

.txt-container {
    width: 100%;
    opacity: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    transform-origin: center center;
    will-change: transform, opacity, filter;
    z-index: 50;
    transform-style: preserve-3d;
    perspective: 1000px;
    cursor: pointer;
    transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), filter 0.4s ease;
}

.txt-container.active {
    animation: atlas-unfold 0.8s var(--transition-snappy) forwards;
}

/* === HOVER: Hologram Emerge - Efecto visible y dramático === */
.txt-container:hover {
    transform: scale(1.15) translateY(-10px);
    filter: brightness(1.2) drop-shadow(0 25px 50px rgba(0, 0, 0, 0.7));
}

/* UI/UX: Brillo dorado intenso */
.txt-container:hover .line-uiux {
    transform: scale(1.05) translateY(-5px);
    filter: brightness(1.4) drop-shadow(0 0 40px rgba(250, 204, 21, 0.8)) drop-shadow(0 0 80px rgba(250, 204, 21, 0.4));
}

/* GAME DESIGNER: Sombra roja expandida */
.txt-container:hover .line-designer {
    transform: scale(1.08) translateY(-3px);
    box-shadow: 1.5cqw 1.5cqw 0 var(--red), 0 0 40px rgba(239, 68, 68, 0.6);
    filter: brightness(1.2);
}

/* INTELLIGENCE SYSTEMS: Glow amarillo intenso */
.txt-container:hover .status-banner {
    transform: scale(1.06) translateY(-2px);
    box-shadow: 1cqw 1cqw 0 #000, 0 0 50px rgba(250, 204, 21, 0.7), 0 0 100px rgba(250, 204, 21, 0.3);
    filter: brightness(1.3);
}

/* Typography Foundation */
.line-title {
    font-family: 'Anton', sans-serif;
    text-transform: uppercase;
    line-height: 0.85;
    -webkit-text-stroke: 1cqw #000;
    paint-order: stroke fill;
    text-align: center;
    white-space: nowrap;
    filter: drop-shadow(1cqw 1cqw 0 #000);
}

.line-uiux {
    font-size: 15cqw;
    color: var(--yellow);
    position: relative;
    z-index: 20;
    line-height: 0.9;
    background: linear-gradient(90deg, var(--yellow) 0%, var(--yellow) 40%, #fff 50%, var(--yellow) 60%, var(--yellow) 100%);
    background-size: 200% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    animation: shine-reflect 4s ease-in-out infinite;
    /* Transición 3D para efecto holograma */
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), filter 0.3s ease;
    transform-style: preserve-3d;
}

.line-designer {
    font-size: 7cqw;
    color: #fff;
    margin-top: 1cqw;
    padding: 0.6cqw 5cqw;
    background: #000;
    box-shadow: 1cqw 1cqw 0 var(--red);
    border: 1px solid rgba(255, 255, 255, 0.2);
    position: relative;
    z-index: 5;
    /* Transición 3D para efecto holograma */
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s, filter 0.3s ease, box-shadow 0.3s ease;
    transform-style: preserve-3d;
}

.status-banner {
    width: 70%;
    height: 7.5cqw;
    background: var(--yellow);
    display: flex;
    align-items: center;
    justify-content: center;
    border: 0.5cqw solid #000;
    box-shadow: 0.8cqw 0.8cqw 0 #000;
    margin-top: 0.2cqw;
    position: relative;
    overflow: hidden;
    opacity: 0;
    /* Transición 3D para efecto holograma */
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.2s, filter 0.3s ease, box-shadow 0.3s ease;
    transform-style: preserve-3d;
}

.status-banner.active {
    animation: banner-reveal 0.6s var(--transition-bouncy) forwards;
}

.hazard-bar {
    position: absolute;
    left: 0;
    width: 6cqw;
    height: 100%;
    background: var(--hazard-gradient);
    background-size: 28px 100%;
    animation: hazard-scroll 1s linear infinite;
}

.hazard-bar.right {
    left: auto;
    right: 0;
}

.status-text {
    font-family: 'Anton', sans-serif;
    color: #000;
    font-size: 3cqw;
    z-index: 5;
}

/* --- Data & Stats --- */
.data-paragraph-container {
    width: 50%;
    position: relative;
    margin-top: 5cqw;
    padding: 2cqw 1cqw;
    background: rgba(10, 20, 25, 0.6);
    border: 1px solid rgba(45, 212, 191, 0.3);
    border-radius: 1cqw;
    opacity: 0;
    backdrop-filter: blur(4px);
    text-align: center;
}

.data-paragraph-container.active {
    animation: element-pop 0.8s ease-out forwards;
}

.data-paragraph {
    font-family: 'Roboto Condensed', sans-serif;
    color: #fff;
    font-size: 2cqw;
    text-transform: uppercase;
}

/* Neural Stats Grid - Optimized Focus */
.stats-grid {
    width: 85%;
    position: absolute;
    bottom: calc(8cqw + 20px);
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 2cqw;
    opacity: 0;
    z-index: 60;
}

/* Efecto de Foco Suavizado: Las otras cajas se atenúan elegantemente */
.stats-grid:hover .stat-box:not(:hover) {
    opacity: 0.7;
    filter: saturate(0.7) brightness(0.85);
    transform: scale(0.95) translateY(3px);
}

/* Asegurar que el tag amarillo siempre sea visible con brillo */
.stats-grid:hover .stat-box:not(:hover) .stat-tag {
    opacity: 1;
    filter: drop-shadow(0 0 8px var(--yellow)) brightness(1.1);
}

.stats-grid.active {
    animation: element-pop 0.7s var(--transition-bouncy) forwards;
}

.stat-box {
    background: linear-gradient(145deg, rgba(8, 20, 28, 0.98) 0%, rgba(3, 12, 18, 0.99) 100%);
    backdrop-filter: blur(16px);
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 1.5cqw;
    aspect-ratio: 2;
    overflow: visible;

    border-radius: 0.8cqw;
    border: 1px solid rgba(45, 212, 191, 0.25);
    box-shadow:
        0 4px 20px rgba(0, 0, 0, 0.6),
        0 0 1px rgba(45, 212, 191, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05),
        inset 0 0 30px rgba(45, 212, 191, 0.03);

    transition:
        transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
        box-shadow 0.4s cubic-bezier(0.23, 1, 0.32, 1),
        border-color 0.3s ease,
        background 0.4s ease;
    will-change: transform, box-shadow;
    cursor: pointer;
    z-index: 1;
}

/* Marco de Energía Interno con gradiente */
.stat-box::before {
    content: "";
    position: absolute;
    inset: 3px;
    border: 1px solid rgba(45, 212, 191, 0.1);
    border-radius: 0.6cqw;
    pointer-events: none;
    background:
        radial-gradient(ellipse at top, rgba(45, 212, 191, 0.03) 0%, transparent 60%),
        radial-gradient(ellipse at bottom, rgba(250, 204, 21, 0.02) 0%, transparent 60%);
    opacity: 1;
    transition: all 0.4s ease;
}

/* Scanline Animada */
.stat-box::after {
    content: "";
    position: absolute;
    top: 0;
    left: 10%;
    width: 80%;
    height: 2px;
    background: linear-gradient(90deg,
            transparent 0%,
            rgba(250, 204, 21, 0.3) 20%,
            var(--yellow) 50%,
            rgba(250, 204, 21, 0.3) 80%,
            transparent 100%);
    opacity: 0;
    border-radius: 2px;
    pointer-events: none;
    transition: opacity 0.3s;
}

/* Tag Amarillo Táctico */
.stat-tag {
    position: absolute;
    top: -1px;
    right: 12%;
    width: 3.5cqw;
    height: 1.2cqw;
    background: linear-gradient(135deg, var(--yellow) 0%, #fde047 50%, var(--yellow) 100%);
    clip-path: polygon(0 0, 100% 0, 100% 100%, 15% 100%);
    z-index: 999;
    box-shadow: 0 2px 8px rgba(250, 204, 21, 0.4);
    transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
