document.addEventListener('DOMContentLoaded', () => {
    // Configuración de elementos e IDs
    const ID_MAP = {
        laser: 'laserLine',
        titles: 'titleDeployment',
        banner: 'protocolBanner',
        paragraph: 'descriptionParagraph',
        stats: 'statsGrid'
    };

    // Recolector de elementos con validación
    const elements = Object.entries(ID_MAP).reduce((acc, [key, id]) => {
        const el = document.getElementById(id);
        if (el) acc[key] = el;
        return acc;
    }, {});

    // Definición de secuencia de animación (Elemento, Retraso)
    const sequence = [
        [elements.laser, 0],
        [elements.titles, 400],
        [elements.banner, 1000],
        [elements.paragraph, 1500],
        [elements.stats, 1900]
    ];

    /**
     * Ejecuta el despliegue de la interfaz
     */
    const deployUI = () => {
        sequence.forEach(([el, delay]) => {
            if (!el) return;

            setTimeout(() => {
                el.classList.add('active');
            }, delay);
        });
    };

    // Inicio diferido para permitir carga de recursos críticos
    setTimeout(deployUI, 500);
});


