            density: 2,
            spawnPoint: { x: 150, y: 450 }, // Spawn relativo al canvas local (centro, abajo)
            spawnDelay: 40,
            _spawn: 0,
            gas: [] as Particle[],
            gasPool: [] as Particle[],
            flameGradientSprites: [] as CachedSprite[],
            lastTime: performance.now(),
            speed: 1
        };

        // Resize inicial
        canvas.width = sim.width;
        canvas.height = sim.height;

        // --- GENERADOR DE GRADIENTES (Copiado y adaptado) ---
        const generateFlameGradients = () => {
            const framesToGenerate = 60; // Reducido para optimización
            const keyframes = [
                { position: 0, start: { radius: 0.3, r: 1, g: 1, b: 0.9, a: 0.8 }, end: { radius: 0.6, a: 0 } },
                { position: 0.15, start: { radius: 0.4, r: 1, g: 0.95, b: 0.2, a: 0.7 }, end: { radius: 1, a: 0 } },
                { position: 0.3, start: { radius: 0.3, r: 1, g: 0.7, b: 0, a: 0.65 }, middle: { radius: 0.6, r: 1, g: 0.5, b: 0, a: 0.6 }, end: { radius: 1, a: 0 } },
                { position: 0.45, start: { radius: 0.35, r: 1, g: 0.4, b: 0, a: 0.6 }, middle: { radius: 0.7, r: 1, g: 0.25, b: 0, a: 0.55 }, end: { radius: 1, a: 0 } },
                { position: 0.6, start: { radius: 0.4, r: 1, g: 0.15, b: 0, a: 0.55 }, middle: { radius: 0.75, r: 0.9, g: 0.1, b: 0, a: 0.5 }, end: { radius: 1, a: 0 } },
                { position: 0.75, start: { radius: 0.3, r: 0.6, g: 0.05, b: 0, a: 0.5 }, middle: { radius: 0.7, r: 0.4, g: 0.02, b: 0, a: 0.45 }, end: { radius: 1, a: 0 } },
                { position: 0.88, start: { radius: 0.35, r: 0.2, g: 0.08, b: 0.02, a: 0.4 }, middle: { radius: 0.7, r: 0.12, g: 0.12, b: 0.12, a: 0.35 }, end: { radius: 1, a: 0 } },
                { position: 1, start: { radius: 0.4, r: 0.1, g: 0.1, b: 0.1, a: 0.15 }, end: { radius: 1, a: 0 } }
            ];

            const computeRGBA = (c: any) => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;
            const interpolate = (start: number, end: number, pos: number) => (end - start) * pos + start;

            keyframes.forEach(k => {
                if (!k.middle) { k.middle = { ...k.start }; (k.start as any).radius = 0; }
                const kAny = k as any;
                ['r', 'g', 'b', 'a'].forEach(p => {
                    kAny.middle[p] = kAny.middle[p] ?? kAny.start[p];
                    kAny.end[p] = kAny.end[p] ?? kAny.middle[p];
                });
            });

            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame = keyframes[i - 1];
                const thisFrame = keyframes[i];
                const frameBatchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= frameBatchSize; j++) {
                    const mult = j / frameBatchSize;
                    const frame = {
                        start: {
                            radius: interpolate((lastFrame.start as any).radius, (thisFrame.start as any).radius, mult),
                            r: interpolate((lastFrame.start as any).r, (thisFrame.start as any).r, mult),
                            g: interpolate((lastFrame.start as any).g, (thisFrame.start as any).g, mult),
                            b: interpolate((lastFrame.start as any).b, (thisFrame.start as any).b, mult),
                            a: interpolate((lastFrame.start as any).a, (thisFrame.start as any).a, mult)
                        },
                        middle: {
                            radius: interpolate((lastFrame.middle as any).radius, (thisFrame.middle as any).radius, mult),
                            r: interpolate((lastFrame.middle as any).r, (thisFrame.middle as any).r, mult),
                            g: interpolate((lastFrame.middle as any).g, (thisFrame.middle as any).g, mult),
                            b: interpolate((lastFrame.middle as any).b, (thisFrame.middle as any).b, mult),
                            a: interpolate((lastFrame.middle as any).a, (thisFrame.middle as any).a, mult)
                        },
                        end: {
                            radius: interpolate((lastFrame.end as any).radius, (thisFrame.end as any).radius, mult),
                            r: interpolate((lastFrame.end as any).r, (thisFrame.end as any).r, mult),
                            g: interpolate((lastFrame.end as any).g, (thisFrame.end as any).g, mult),
                            b: interpolate((lastFrame.end as any).b, (thisFrame.end as any).b, mult),
                            a: interpolate((lastFrame.end as any).a, (thisFrame.end as any).a, mult)
                        }
                    };

                    const sprite = new CachedSprite({
                        width: sim.gasRadius * 2,
                        height: sim.gasRadius * 2,
                        draw(ctx: CanvasRenderingContext2D, { width, height }: { width: number; height: number }) {
                            const center = width / 2;
                            const gradient = ctx.createRadialGradient(center, height * 0.7, 0, center, center, center);
                            gradient.addColorStop(frame.start.radius, computeRGBA(frame.start));
                            gradient.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                            gradient.addColorStop(frame.end.radius, computeRGBA(frame.end));
                            ctx.fillStyle = gradient;
                            ctx.fillRect(0, 0, width, height);
                        }
                    });
                    sim.flameGradientSprites.push(sprite);
                }
            }
        };

        // --- POOL DE PARTÍCULAS ---
        const createParticle = (): Particle => ({
            remove: false, x: 0, y: 0, size: 0, speedX: 0, speedY: 0, lifespan: 0, age: 0,
            recycle() { this.remove = false; sim.gasPool.push(this); }
        });

        const spawnParticle = (initData: any) => {
            const g = sim.gasPool.pop() || createParticle();
            g.age = 0;
            g.lifespan = Math.floor(Math.random() * 1200 + 1500); // Vida más corta para ajustarse
            g.size = sim.gasRadius;
            g.x = initData.x;
            g.y = initData.y;
            g.speedX = initData.speedX;
            g.speedY = initData.speedY;
            sim.gas.push(g);
        };

        // --- BUCLE DE ANIMACIÓN ---
        const loop = () => {
            const now = performance.now();
            const delta = now - sim.lastTime;
            sim.lastTime = now;

            const simTime = delta * sim.speed;
            const simSpeed = sim.speed * (delta / 16.67);

            // LOGICA TICK
            sim._spawn += simTime;
            while (sim._spawn >= sim.spawnDelay) {
                sim._spawn -= sim.spawnDelay;
                const angle = (sim.direction - sim.directionSpread / 2) * MyMath.toRad;
                const rotateIncrement = (sim.directionSpread * MyMath.toRad) / sim.density;

                for (let i = 0; i < sim.density; i++) {
                    const subAngle = angle + (rotateIncrement * i) + Math.random() * rotateIncrement;
                    const rand = Math.random();
                    const subSpeed = sim.velocity * (1 - (1 - rand * rand) * sim.velocitySpread);
                    spawnParticle({
                        x: sim.spawnPoint.x,
                        y: sim.spawnPoint.y,
                        speedX: Math.sin(subAngle) * subSpeed,
                        speedY: -Math.cos(subAngle) * subSpeed
                    });
                }
            }

            const damp = 1 - 0.01 * simSpeed; // Menos damping
            const gravity = 0.05; // Menos gravedad

            for (let i = sim.gas.length - 1; i >= 0; i--) {
                const g = sim.gas[i];
                g.age += simTime;
                g.x += g.speedX * simSpeed;
                g.y += g.speedY * simSpeed;
                g.speedX *= damp;
                g.speedY = g.speedY * damp - gravity * simSpeed;

                if (g.y < -g.size || g.y > sim.height + g.size) g.remove = true;
                if (g.remove) {
                    sim.gas.splice(i, 1);
                    g.recycle();
                }
            }

            // LOGICA DRAW
            ctx.clearRect(0, 0, sim.width, sim.height);
            // Global composite para mezclar humo
            ctx.globalCompositeOperation = 'screen'; 

            for (let i = sim.gas.length - 1; i >= 0; i--) {
                const g = sim.gas[i];
                const life = Math.min(1, g.age / g.lifespan);
                const spriteIndex = Math.floor(life * (sim.flameGradientSprites.length - 1));
                const sprite = sim.flameGradientSprites[spriteIndex];
                if (sprite) {
                    sprite.x = g.x - g.size;
                    sprite.y = g.y - g.size;
                    sprite.drawOnContext(ctx);
                }
            }
            ctx.globalCompositeOperation = 'source-over';

            animationFrameId.current = requestAnimationFrame(loop);
        };

        // INICIO
        generateFlameGradients();
        loop();

        return () => {
            cancelAnimationFrame(animationFrameId.current);
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative flex items-end justify-center group cursor-pointer ${interactionProps.className}`}
            style={{ width: '30vh', height: '60vh' }} // Contenedor vertical
            onMouseEnter={interactionProps.onMouseEnter}
            onMouseLeave={interactionProps.onMouseLeave}
        >
            {/* CANVAS HUMO (Detrás) */}
            <canvas 
                ref={canvasRef} 
                className="absolute bottom-[20%] left-1/2 transform -translate-x-1/2 pointer-events-none opacity-90 mix-blend-screen"
                style={{ width: '100%', height: '150%' }} // Escalar canvas visualmente
            />

            {/* IMAGEN BARRIL (Delante) */}
            <img 
                src="https://i.imgur.com/FabMJD9.png" 
                alt="Barril Tóxico" 
                className="relative z-10 w-full object-contain object-bottom drop-shadow-[0_0_25px_rgba(242,208,25,0.2)] transition-all duration-300 group-hover:brightness-110 group-hover:drop-shadow-[0_0_35px_rgba(242,208,25,0.5)]"
                draggable="false"
            />

            {/* UI Label on Hover */}
            <div className="absolute -bottom-8 left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <div className="bg-black/80 border border-[#F2D019] px-3 py-1">
                    <span className="font-['Teko'] text-[#F2D019] text-xl tracking-widest">CONTACTO</span>
                </div>
            </div>
        </div>
    );
});

