import React, { useEffect, useRef } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface BarrelSmokeProps {
    onClick: () => void;
}

export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({ onClick }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Sistema de interacción (Tooltip y cursor)
    const interaction = useImageInteraction("TOXIC BARREL: UPLINK", "https://i.imgur.com/FabMJD9.png");

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        // --- CONFIGURACIÓN DE LA SIMULACIÓN ---
        // Ajustado para encajar visualmente con el barril
        const config = {
            width: 300,
            height: 600,
            direction: 0,           // 0 grados = Arriba (en canvas Y negativo)
            directionSpread: 35,    // Ángulo de apertura del humo
            velocity: 2.5,          // Velocidad de subida
            velocitySpread: 0.4,    // Variación de velocidad
            gasRadius: 45,          // Tamaño de partícula
            density: 2,             // Partículas por tick (reducido para no saturar)
            spawnDelay: 40,         // Milisegundos entre spawns
            spawnPoint: { x: 150, y: 480 } // Punto de origen (relativo al canvas 300x600)
        };

        // Estado interno mutable
        let _spawnTimer = 0;
        let lastTime = performance.now();
        let animationFrameId: number;

        // Pools para evitar Garbage Collection
        const gasParticles: GasParticle[] = [];
        const gasPool: GasParticle[] = [];
        const flameSprites: HTMLCanvasElement[] = [];

        // Setup inicial del Canvas
        canvas.width = config.width;
        canvas.height = config.height;

        // --- CLASE PARTÍCULA ---
        class GasParticle {
            x = 0;
            y = 0;
            speedX = 0;
            speedY = 0;
            size = 0;
            lifespan = 0;
            age = 0;
            remove = false;

            reset(initX: number, initY: number, vx: number, vy: number) {
                this.x = initX;
                this.y = initY;
                this.speedX = vx;
                this.speedY = vy;
                this.size = config.gasRadius;
                this.lifespan = Math.random() * 1000 + 2000; // 2-3 segundos de vida
                this.age = 0;
                this.remove = false;
            }
        }

        // --- GENERADOR DE SPRITES (GRADIENTES CACHEADOS) ---
        const generateFlameSprites = () => {
            const frames = 60; // Cantidad de estados de la animación de color

            // Definición de colores clave (Amarillo -> Naranja -> Rojo -> Humo Gris)
            const keyframes: any[] = [
                { pos: 0,    color: { r: 255, g: 255, b: 200, a: 0.9 }, radius: 0.2 }, // Núcleo caliente
                { pos: 0.2,  color: { r: 255, g: 180, b: 0,   a: 0.8 }, radius: 0.4 }, // Fuego
                { pos: 0.4,  color: { r: 200, g: 80,  b: 0,   a: 0.6 }, radius: 0.6 }, // Rojo oscuro
                { pos: 0.65, color: { r: 50,  g: 50,  b: 50,  a: 0.4 }, radius: 0.7 }, // Humo denso
                { pos: 1.0,  color: { r: 0,   g: 0,   b: 0,   a: 0.0 }, radius: 0.8 }  // Disipación
            ];

            // Interpolador lineal de color
            const lerp = (start: number, end: number, t: number) => start + (end - start) * t;

            for (let i = 0; i < frames; i++) {
                const t = i / (frames - 1);

                // Encontrar keyframes adyacentes
                let k1 = keyframes[0];
                let k2 = keyframes[keyframes.length - 1];

                for (let k = 0; k < keyframes.length - 1; k++) {
                    if (t >= keyframes[k].pos && t <= keyframes[k+1].pos) {
                        k1 = keyframes[k];
                        k2 = keyframes[k+1];
                        break;
                    }
                }

                // Normalizar t entre los dos keyframes
                const localT = (t - k1.pos) / (k2.pos - k1.pos);

                const r = Math.floor(lerp(k1.color.r, k2.color.r, localT));
                const g = Math.floor(lerp(k1.color.g, k2.color.g, localT));
                const b = Math.floor(lerp(k1.color.b, k2.color.b, localT));
                const a = lerp(k1.color.a, k2.color.a, localT);

                const radiusStart = lerp(k1.radius * 0.5, k2.radius * 0.5, localT); // Radio interno del gradiente
                const radiusEnd = 1.0; 

                // Crear canvas temporal para este frame
                const sCanvas = document.createElement('canvas');
                const size = config.gasRadius * 2;
                sCanvas.width = size;
                sCanvas.height = size;
                const sCtx = sCanvas.getContext('2d')!;

                const center = size / 2;
                const gradient = sCtx.createRadialGradient(center, center, size * radiusStart, center, center, size * 0.5);

                gradient.addColorStop(0, `rgba(${r},${g},${b},${a})`);
                gradient.addColorStop(1, `rgba(${r},${g},${b},0)`);

                sCtx.fillStyle = gradient;
                sCtx.fillRect(0, 0, size, size);

                flameSprites.push(sCanvas);
            }
        };

        // --- BUCLE PRINCIPAL ---
        const loop = () => {
            const now = performance.now();
            const delta = now - lastTime;
            lastTime = now;

            // Normalización de velocidad (basada en 60fps)
            const dt = Math.min(delta, 50); // Cap delta para evitar saltos enormes
            const simSpeed = dt / 16.67;

            // 1. SPAWN
            _spawnTimer += dt;
            while (_spawnTimer >= config.spawnDelay) {
                _spawnTimer -= config.spawnDelay;

                const angleRad = (config.direction - 90) * (Math.PI / 180); // -90 para que 0 sea 'arriba'
                const spreadRad = (config.directionSpread * (Math.PI / 180));

                for (let i = 0; i < config.density; i++) {
                    // Ángulo aleatorio dentro del spread
                    const angle = angleRad + (Math.random() - 0.5) * spreadRad;
                    const speed = config.velocity * (1 + (Math.random() - 0.5) * config.velocitySpread);

                    const particle = gasPool.pop() || new GasParticle();
                    particle.reset(
                        config.spawnPoint.x, 
                        config.spawnPoint.y,
                        Math.cos(angle) * speed,
                        Math.sin(angle) * speed
                    );
                    gasParticles.push(particle);
                }
            }

            // 2. UPDATE & DRAW
            ctx.clearRect(0, 0, config.width, config.height);
            // 'lighter' crea el efecto de fuego brillante al superponer partículas
            ctx.globalCompositeOperation = 'lighter'; 

            for (let i = gasParticles.length - 1; i >= 0; i--) {
                const p = gasParticles[i];
                p.age += dt;

                // Física simple
                p.x += p.speedX * simSpeed;
                p.y += p.speedY * simSpeed; // speedY es negativo para subir

                // Arrastre (Damping) y "Gravedad Inversa" (Flotabilidad)
                p.speedX *= 0.98; 
                p.speedY -= 0.05 * simSpeed; // Acelera hacia arriba

                // Ciclo de vida
                if (p.age >= p.lifespan) {
                    gasParticles.splice(i, 1);
                    gasPool.push(p);
                    continue;
                }

                // Renderizado
                const lifeProgress = p.age / p.lifespan;
                const spriteIndex = Math.floor(lifeProgress * (flameSprites.length - 1));
                const sprite = flameSprites[spriteIndex];

                if (sprite) {
                    // Dibujar centrado
                    ctx.drawImage(sprite, p.x - p.size, p.y - p.size);
                }
            }

            // Restaurar modo de mezcla para el siguiente frame (si hubiera otros elementos)
            ctx.globalCompositeOperation = 'source-over';

            animationFrameId = requestAnimationFrame(loop);
        };

        // INICIAR
        generateFlameSprites();
        loop();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div 
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative group cursor-pointer ${interaction.className}`}
            style={{ 
                width: '30vh', 
                height: '60vh',
