    </div>

    <script>
        // ============================================
        // UTILIDADES MATEMÁTICAS
        // ============================================
        const MyMath = {
            toRad: Math.PI / 180,
            toDeg: 180 / Math.PI,
            pointDist: (x1, y1, x2, y2) => Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2),
            pointAngle: (x1, y1, x2, y2) => Math.atan2(x2 - x1, y1 - y2),
            splitVector: (speed, angle) => ({
                x: Math.sin(angle) * speed,
                y: -Math.cos(angle) * speed
            })
        };

        // ============================================
        // CLASE STAGE (Gestión del Canvas)
        // ============================================
        class Stage {
            constructor(options) {
                this.canvas = document.getElementById('smoke-canvas');
                this.ctx = this.canvas.getContext('2d');
                this.width = window.innerWidth;
                this.height = window.innerHeight;
                this.speed = 1;
                this.lastTime = performance.now();

                this.resize();
                window.addEventListener('resize', () => this.resize());

                this.onTick = null;
                this.onDraw = null;

                this.loop();
            }

            resize() {
                this.width = window.innerWidth;
                this.height = window.innerHeight;
                this.canvas.width = this.width;
                this.canvas.height = this.height;
            }

            createCachedSprite(options) {
                return new CachedSprite(options);
            }

            loop() {
                const now = performance.now();
                const delta = now - this.lastTime;
                this.lastTime = now;

                const simTime = delta * this.speed;
                const simSpeed = this.speed * (delta / 16.67);

                if (this.onTick) {
                    this.onTick({
                        simTime,
                        simSpeed,
                        width: this.width,
                        height: this.height
                    });
                }

                if (this.onDraw) {
                    this.onDraw({
                        ctx: this.ctx,
                        width: this.width,
                        height: this.height
                    });
                }

                requestAnimationFrame(() => this.loop());
            }
        }

        // ============================================
        // CLASE CACHED SPRITE
        // ============================================
        class CachedSprite {
            constructor(options) {
                this.width = options.width;
                this.height = options.height;
                this.drawFn = options.draw;
                this.x = 0;
                this.y = 0;

                this.canvas = document.createElement('canvas');
                this.ctx = this.canvas.getContext('2d');
                this.resize(this.width, this.height);
                this.redraw();
            }

            resize(width, height) {
                this.width = width;
                this.height = height;
                this.canvas.width = width;
                this.canvas.height = height;
            }

            redraw() {
                this.ctx.clearRect(0, 0, this.width, this.height);
                this.drawFn(this.ctx, { width: this.width, height: this.height });
            }

            drawOnContext(ctx) {
                ctx.drawImage(this.canvas, this.x, this.y);
            }
        }

        // ============================================
        // SIMULACIÓN DE HUMO
        // ============================================
        const simulation = {
            stage: null,
            direction: 0,
            directionSpread: 360,
            velocity: 3,
            velocitySpread: 0.65,
            gasRadius: 55,
            density: 8,
            // Punto de spawn ESTÁTICO (centro-abajo de la pantalla)
