        };

        // Generar gradientes de llama prerenderizados
        simulation.generateFlameGradients = function () {
            const { stage, gasRadius, flameGradientSprites } = simulation;
            const framesToGenerate = 120;

            const keyframes = [
                // Núcleo blanco-amarillo brillante (centro de la llama)
                {
                    position: 0,
                    start: { radius: 0.3, r: 1, g: 1, b: 0.9, a: 0.8 },
                    end: { radius: 0.6, a: 0 }
                },
                // Amarillo intenso
                {
                    position: 0.15,
                    start: { radius: 0.4, r: 1, g: 0.95, b: 0.2, a: 0.7 },
                    end: { radius: 1, a: 0 }
                },
                // Amarillo-naranja brillante
                {
                    position: 0.3,
                    start: { radius: 0.3, r: 1, g: 0.7, b: 0, a: 0.65 },
                    middle: { radius: 0.6, r: 1, g: 0.5, b: 0, a: 0.6 },
                    end: { radius: 1, a: 0 }
                },
                // Naranja intenso
                {
                    position: 0.45,
                    start: { radius: 0.35, r: 1, g: 0.4, b: 0, a: 0.6 },
                    middle: { radius: 0.7, r: 1, g: 0.25, b: 0, a: 0.55 },
                    end: { radius: 1, a: 0 }
                },
                // Rojo-naranja
                {
                    position: 0.6,
                    start: { radius: 0.4, r: 1, g: 0.15, b: 0, a: 0.55 },
                    middle: { radius: 0.75, r: 0.9, g: 0.1, b: 0, a: 0.5 },
                    end: { radius: 1, a: 0 }
                },
                // Rojo oscuro con inicio de humo
                {
                    position: 0.75,
                    start: { radius: 0.3, r: 0.6, g: 0.05, b: 0, a: 0.5 },
                    middle: { radius: 0.7, r: 0.4, g: 0.02, b: 0, a: 0.45 },
                    end: { radius: 1, a: 0 }
                },
                // Humo oscuro con restos de brasa
                {
                    position: 0.88,
                    start: { radius: 0.35, r: 0.2, g: 0.08, b: 0.02, a: 0.4 },
                    middle: { radius: 0.7, r: 0.12, g: 0.12, b: 0.12, a: 0.35 },
                    end: { radius: 1, a: 0 }
                },
                // Humo tenue final
                {
                    position: 1,
                    start: { radius: 0.4, r: 0.1, g: 0.1, b: 0.1, a: 0.15 },
                    end: { radius: 1, a: 0 }
                }
            ];

            const computeRGBA = c => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;
            const interpolate = (start, end, pos) => (end - start) * pos + start;

            // Expandir keyframes
            keyframes.forEach(k => {
                if (!k.middle) {
                    k.middle = { ...k.start };
                    k.start.radius = 0;
                }

                k.middle.r = k.middle.r ?? k.start.r;
                k.middle.g = k.middle.g ?? k.start.g;
                k.middle.b = k.middle.b ?? k.start.b;
                k.middle.a = k.middle.a ?? k.start.a;

                k.end.r = k.end.r ?? k.middle.r;
                k.end.g = k.end.g ?? k.middle.g;
                k.end.b = k.end.b ?? k.middle.b;
                k.end.a = k.end.a ?? k.middle.a;
            });

            // Generar frames
            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame = keyframes[i - 1];
                const thisFrame = keyframes[i];
                const frameBatchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= frameBatchSize; j++) {
                    const mult = j / frameBatchSize;

                    const frame = {
                        start: {
                            radius: interpolate(lastFrame.start.radius, thisFrame.start.radius, mult),
                            r: interpolate(lastFrame.start.r, thisFrame.start.r, mult),
                            g: interpolate(lastFrame.start.g, thisFrame.start.g, mult),
                            b: interpolate(lastFrame.start.b, thisFrame.start.b, mult),
                            a: interpolate(lastFrame.start.a, thisFrame.start.a, mult)
                        },
                        middle: {
                            radius: interpolate(lastFrame.middle.radius, thisFrame.middle.radius, mult),
                            r: interpolate(lastFrame.middle.r, thisFrame.middle.r, mult),
                            g: interpolate(lastFrame.middle.g, thisFrame.middle.g, mult),
                            b: interpolate(lastFrame.middle.b, thisFrame.middle.b, mult),
                            a: interpolate(lastFrame.middle.a, thisFrame.middle.a, mult)
                        },
                        end: {
                            radius: interpolate(lastFrame.end.radius, thisFrame.end.radius, mult),
                            r: interpolate(lastFrame.end.r, thisFrame.end.r, mult),
                            g: interpolate(lastFrame.end.g, thisFrame.end.g, mult),
                            b: interpolate(lastFrame.end.b, thisFrame.end.b, mult),
                            a: interpolate(lastFrame.end.a, thisFrame.end.a, mult)
                        }
                    };

                    const sprite = stage.createCachedSprite({
                        width: gasRadius * 2,
                        height: gasRadius * 2,
                        draw(ctx, { width, height }) {
                            const center = width / 2;
                            const gradient = ctx.createRadialGradient(center, height * 0.7, 0, center, center, center);
                            gradient.addColorStop(frame.start.radius, computeRGBA(frame.start));
                            gradient.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                            gradient.addColorStop(frame.end.radius, computeRGBA(frame.end));
                            ctx.fillStyle = gradient;
                            ctx.fillRect(0, 0, width, height);
                        }
                    });

                    flameGradientSprites.push(sprite);
                }
            }
        };

        // Tick de simulación
        function tick({ simTime, simSpeed, width, height }) {
            const { gas, gasPool, spawnPoint } = simulation;

            // Spawn gas (ESTÁTICO - no sigue el cursor)
            simulation._spawn += simTime;
            while (simulation._spawn >= simulation.spawnDelay) {
                simulation._spawn -= simulation.spawnDelay;

                const angle = (simulation.direction - simulation.directionSpread / 2) * MyMath.toRad;
                const speed = simulation.velocity;
                const gasCount = simulation.density;
                const rotateIncrement = (simulation.directionSpread * MyMath.toRad) / gasCount;

                for (let i = 0; i < gasCount; i++) {
                    const subAngle = angle + (rotateIncrement * i) + Math.random() * rotateIncrement;
                    const rand = Math.random();
                    const subSpeed = speed * (1 - (1 - rand * rand) * simulation.velocitySpread);

                    simulation.Gas.new({
                        x: spawnPoint.x,
                        y: spawnPoint.y,
                        speedX: Math.sin(subAngle) * subSpeed,
                        speedY: -Math.cos(subAngle) * subSpeed
                    });
                }
            }

            const damp = 1 - 0.02 * simSpeed;
            const gravity = 0.08;

            for (let i = gas.length - 1; i >= 0; i--) {
                const g = gas[i];
                g.age += simTime;
                g.x += g.speedX * simSpeed;
                g.y += g.speedY * simSpeed;
                g.speedX *= damp;
                g.speedY = g.speedY * damp - gravity * simSpeed;

                if (g.y < -g.size || g.x < -g.size || g.x > width + g.size) {
                    g.remove = true;
                }

                if (g.remove) {
                    gas.splice(i, 1);
                    g.recycle();
                }
            }
        }

        // Renderizado
        function draw({ ctx, width, height }) {
            const { gas, flameGradientSprites } = simulation;

            ctx.clearRect(0, 0, width, height);

            for (let i = gas.length - 1; i >= 0; i--) {
                const g = gas[i];
                const life = Math.min(1, g.age / g.lifespan);
                const spriteIndex = Math.floor(life * (flameGradientSprites.length - 1));
                const sprite = flameGradientSprites[spriteIndex];

                sprite.x = g.x - g.size;
                sprite.y = g.y - g.size;
                sprite.drawOnContext(ctx);
            }
        }

        // Clase Gas
        simulation.Gas = function () {
            this.remove = false;
            this.x = 0;
            this.y = 0;
            this.size = 0;
            this.speedX = 0;
            this.speedY = 0;
            this.lifespan = 0;
            this.age = 0;
        };

        simulation.Gas.new = function (initData) {
            const g = simulation.gasPool.pop() || new simulation.Gas();
            g.age = 0;
            g.lifespan = Math.floor(Math.random() * 1200 + 2500);
            g.size = simulation.gasRadius;
            g.x = initData.x;
            g.y = initData.y;
            g.speedX = initData.speedX;
            g.speedY = initData.speedY;
            simulation.gas.push(g);
            return g;
        };

        simulation.Gas.prototype.recycle = function () {
            this.remove = false;
            simulation.gasPool.push(this);
        };

        // Iniciar simulación
        simulation.init();
    </script>
</body>

</html>

