import React, { useEffect, useRef } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface BarrelSmokeProps {
    onClick: () => void;
}

export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({ onClick }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Configuración de interacción para el sistema global
    const interactionProps = useImageInteraction("TOXIC BARREL: UPLINK", "https://i.imgur.com/fr9Bz6G.png");

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let animationFrameId: number;

        // --- CONFIGURACIÓN DE LA SIMULACIÓN ---
        // Ajustada para funcionar dentro del componente (coordenadas locales)
        const config = {
            width: 300,
            height: 600,
            spawnPoint: { x: 150, y: 480 }, // Punto de emisión ajustado a la boca del barril
            gasRadius: 45,
            density: 2, // Cantidad de partículas por ciclo
            spawnDelay: 40, // ms entre emisiones
            velocity: 2.2,
            velocitySpread: 0.5,
            direction: 0, // 0 es hacia arriba en nuestra lógica ajustada
            directionSpread: 45
        };

        // Estado mutable de la simulación
        const state = {
            gas: [] as any[],
            gasPool: [] as any[],
            flameGradientSprites: [] as HTMLCanvasElement[], // Sprites cacheados
            lastTime: performance.now(),
            spawnTimer: 0
        };

        // Dimensionar canvas
        canvas.width = config.width;
        canvas.height = config.height;

        // --- UTILIDADES ---
        const toRad = Math.PI / 180;
        const interpolate = (start: number, end: number, pos: number) => (end - start) * pos + start;
        const computeRGBA = (c: any) => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;

        // --- CLASE CACHED SPRITE (Simplificada) ---
        // Genera sprites pre-renderizados para evitar dibujar gradientes en cada frame
        const createCachedSprite = (drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void) => {
            const c = document.createElement('canvas');
            const dim = config.gasRadius * 2;
            c.width = dim;
            c.height = dim;
            const cx = c.getContext('2d');
            if (cx) drawFn(cx, dim, dim);
            return c;
        };

        // --- GENERADOR DE GRADIENTES (Lógica original portada) ---
        const generateFlameGradients = () => {
            const framesToGenerate = 60; // Optimización: 60 frames son suficientes para suavidad
            const keyframes = [
                // Núcleo blanco-amarillo
                { position: 0, start: { radius: 0.1, r: 1, g: 1, b: 0.9, a: 0.9 }, end: { radius: 0.4, a: 0 } },
                // Amarillo intenso
                { position: 0.15, start: { radius: 0.2, r: 1, g: 0.95, b: 0.2, a: 0.8 }, end: { radius: 0.7, a: 0 } },
                // Amarillo-naranja
                { position: 0.3, start: { radius: 0.15, r: 1, g: 0.7, b: 0, a: 0.75 }, middle: { radius: 0.4, r: 1, g: 0.5, b: 0, a: 0.7 }, end: { radius: 0.8, a: 0 } },
                // Naranja
                { position: 0.45, start: { radius: 0.2, r: 1, g: 0.4, b: 0, a: 0.7 }, middle: { radius: 0.5, r: 1, g: 0.25, b: 0, a: 0.6 }, end: { radius: 0.9, a: 0 } },
                // Rojo
                { position: 0.6, start: { radius: 0.25, r: 1, g: 0.15, b: 0, a: 0.6 }, middle: { radius: 0.6, r: 0.9, g: 0.1, b: 0, a: 0.5 }, end: { radius: 1, a: 0 } },
                // Rojo oscuro/Humo
                { position: 0.75, start: { radius: 0.2, r: 0.6, g: 0.05, b: 0, a: 0.5 }, middle: { radius: 0.6, r: 0.4, g: 0.02, b: 0, a: 0.4 }, end: { radius: 1, a: 0 } },
                // Humo final
                { position: 1, start: { radius: 0.3, r: 0.1, g: 0.1, b: 0.1, a: 0.2 }, end: { radius: 1, a: 0 } }
            ];

            // Normalizar datos intermedios
            keyframes.forEach((k: any) => {
                if (!k.middle) { k.middle = { ...k.start }; k.start.radius = 0; }
                ['r', 'g', 'b', 'a'].forEach(p => {
                    k.middle[p] = k.middle[p] ?? k.start[p];
                    k.end[p] = k.end[p] ?? k.middle[p];
                });
            });

            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame: any = keyframes[i - 1];
                const thisFrame: any = keyframes[i];
                const batchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= batchSize; j++) {
                    const mult = j / batchSize;
                    const frame: any = {};
                    ['start', 'middle', 'end'].forEach(key => {
                        frame[key] = {};
                        ['radius', 'r', 'g', 'b', 'a'].forEach(prop => {
                            frame[key][prop] = interpolate(lastFrame[key][prop] || 0, thisFrame[key][prop] || 0, mult);
                        });
                    });

                    const sprite = createCachedSprite((ctx, w, h) => {
                        const center = w / 2;
                        // Gradiente radial
                        const grad = ctx.createRadialGradient(center, center * 1.2, 0, center, center, center);
                        grad.addColorStop(frame.start.radius, computeRGBA(frame.start));
                        if(frame.middle.radius > frame.start.radius) grad.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                        grad.addColorStop(frame.end.radius, computeRGBA(frame.end));

                        ctx.fillStyle = grad;
                        ctx.fillRect(0, 0, w, h);
                    });

                    state.flameGradientSprites.push(sprite);
                }
            }
        };

        // --- SISTEMA DE PARTÍCULAS ---
        const spawnParticle = () => {
            const angle = (config.direction - config.directionSpread / 2) * toRad;
            const spread = (config.directionSpread * toRad) / config.density;

            for (let i = 0; i < config.density; i++) {
                const subAngle = angle + (spread * i) + Math.random() * spread;
                const speed = config.velocity * (1 - (1 - Math.random() * Math.random()) * config.velocitySpread);

                // Reciclar o crear nueva
                const p = state.gasPool.pop() || { x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 0, size: 0 };

                p.x = config.spawnPoint.x;
                p.y = config.spawnPoint.y;
                p.vx = Math.sin(subAngle) * speed;
                p.vy = -Math.cos(subAngle) * speed; // Negativo para subir en Canvas
                p.age = 0;
                p.life = Math.random() * 1000 + 2000;
                p.size = config.gasRadius;
                state.gas.push(p);
            }
        };

        // --- LOOP PRINCIPAL ---
        const tick = () => {
            const now = performance.now();
            const delta = now - state.lastTime;
            state.lastTime = now;

            // Simulación step (cap en 60ms para evitar saltos grandes)
            const simTime = Math.min(delta, 60); 
            const simSpeed = simTime / 16.67;

            // Spawn
            state.spawnTimer += simTime;
            while (state.spawnTimer >= config.spawnDelay) {
                state.spawnTimer -= config.spawnDelay;
                spawnParticle();
            }

            const damp = 1 - 0.01 * simSpeed;
            const gravity = -0.04; // Flotabilidad negativa (hacia arriba)

            // Update Physics
            for (let i = state.gas.length - 1; i >= 0; i--) {
                const p = state.gas[i];
                p.age += simTime;
                p.x += p.vx * simSpeed;
                p.y += p.vy * simSpeed;
                p.vx *= damp;
                p.vy = (p.vy * damp) + (gravity * simSpeed);

                // Matar partícula
                if (p.age >= p.life) {
                    state.gas.splice(i, 1);
                    state.gasPool.push(p);
                }
            }

            // Draw
            ctx.clearRect(0, 0, config.width, config.height);

            // 'Screen' mode para que el fuego se vea brillante al superponerse
            ctx.globalCompositeOperation = 'screen'; 

            for (let i = 0; i < state.gas.length; i++) {
                const p = state.gas[i];
                const progress = Math.min(1, p.age / p.life);
                const frameIdx = Math.floor(progress * (state.flameGradientSprites.length - 1));
                const sprite = state.flameGradientSprites[frameIdx];

                if (sprite) {
                    // Dibujar centrado en la posición de la partícula
                    ctx.drawImage(sprite, p.x - p.size, p.y - p.size);
                }
            }

            ctx.globalCompositeOperation = 'source-over';

            animationFrameId = requestAnimationFrame(tick);
        };

        // Iniciar
        generateFlameGradients();
        tick();

        // Cleanup
        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative flex items-end justify-center group cursor-pointer ${interactionProps.className}`}
            style={{ width: '30vh', height: '60vh' }}
            onMouseEnter={interactionProps.onMouseEnter}
            onMouseLeave={interactionProps.onMouseLeave}
        >
            {/* CANVAS HUMO (Detrás de la imagen) */}
            <canvas 
                ref={canvasRef} 
                className="absolute left-1/2 bottom-0 transform -translate-x-1/2 pointer-events-none mix-blend-screen opacity-90"
                style={{ width: '100%', height: '120%', zIndex: 0, bottom: '-10%' }}
            />

            {/* IMAGEN BARRIL (Delante) */}
            <img 
                src="https://i.imgur.com/fr9Bz6G.png" 
                alt="Barril Tóxico" 
                className="relative z-10 w-full h-full object-contain object-bottom drop-shadow-[0_0_25px_rgba(242,208,25,0.2)] transition-all duration-300 group-hover:brightness-110 group-hover:drop-shadow-[0_0_35px_rgba(242,208,25,0.5)]"
                draggable="false"
            />

            {/* UI Label on Hover */}
            <div className="absolute top-[30%] left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-20 pointer-events-none">
                <div className="bg-black/80 border border-[#F2D019] px-3 py-1 skew-x-[-15deg]">
                    <span className="block transform skew-x-[15deg] font-['Teko'] text-[#F2D019] text-xl tracking-widest leading-none">CONTACTO</span>
                </div>
                <div className="w-[1px] h-8 bg-[#F2D019] mx-auto opacity-50" />
            </div>
        </div>
    );
});

