import React, { useEffect, useRef, useCallback } from 'react';

interface BarrelSmokeProps {
    onClick: () => void;
    /** Punto de spawn del fuego (x: 0-1, y: 0-1 relativo al contenedor) */
    spawnPosition?: { x: number; y: number };
    /** Intensidad del efecto (1 = normal, 2 = doble) */
    intensity?: number;
}

interface Particle {
    x: number;
    y: number;
    vx: number;
    vy: number;
    age: number;
    life: number;
    size: number;
}

interface SimulationState {
    gas: Particle[];
    gasPool: Particle[];
    flameGradientSprites: HTMLCanvasElement[];
    lastTime: number;
    spawnTimer: number;
}

// ============================================
// COMPONENTE BARREL SMOKE MEJORADO
// ============================================
export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({
    onClick,
    spawnPosition = { x: 0.5, y: 0.8 },
    intensity = 1
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let animationFrameId: number;

        // ============================================
        // CONFIGURACIÓN DE LA SIMULACIÓN (MEJORADA)
        // ============================================
        const config = {
            width: 300,
            height: 600,
            // Spawn point calculado desde la posición relativa
            spawnPoint: {
                x: 300 * spawnPosition.x,
                y: 600 * spawnPosition.y
            },
            // Tamaño de las partículas de fuego
            gasRadius: 55,
            // Densidad de partículas (más = más fuego)
            density: Math.round(8 * intensity),
            // Delay entre spawns (menor = más partículas)
            spawnDelay: 25,
            // Velocidad base de las partículas
            velocity: 3.5,
            velocitySpread: 0.65,
            // Dirección del fuego (0 = hacia arriba)
            direction: 0,
            // Spread angular (grados) - más contenido para efecto de chimenea
            directionSpread: 40,
            // Física mejorada
            dampening: 0.015,  // Menor = menos fricción, movimiento más suave
            gravity: -0.06,   // Negativo = flotabilidad hacia arriba
            // Vida de las partículas (más larga = efecto más lento y visible)
            lifespanMin: 2500,
            lifespanMax: 3700
        };

        // Estado mutable de la simulación
        const state: SimulationState = {
            gas: [],
            gasPool: [],
            flameGradientSprites: [],
            lastTime: performance.now(),
            spawnTimer: 0
        };

        // Dimensionar canvas
        canvas.width = config.width;
        canvas.height = config.height;

        // ============================================
        // UTILIDADES
        // ============================================
        const toRad = Math.PI / 180;
        const interpolate = (start: number, end: number, pos: number) =>
            (end - start) * pos + start;
        const computeRGBA = (c: { r: number; g: number; b: number; a: number }) =>
            `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;

        // ============================================
        // CREAR SPRITE CACHEADO
        // ============================================
        const createCachedSprite = (
            drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void
        ): HTMLCanvasElement => {
            const spriteCanvas = document.createElement('canvas');
            const dim = config.gasRadius * 2;
            spriteCanvas.width = dim;
            spriteCanvas.height = dim;
            const spriteCtx = spriteCanvas.getContext('2d');
            if (spriteCtx) drawFn(spriteCtx, dim, dim);
            return spriteCanvas;
        };

        // ============================================
        // GENERADOR DE GRADIENTES DE LLAMA (MEJORADO)
        // Con más énfasis en colores de fuego y menos humo
        // ============================================
        const generateFlameGradients = () => {
            const framesToGenerate = 120;

            // Keyframes mejorados: 75% fuego, 25% humo
            const keyframes = [
                // Núcleo blanco-amarillo brillante (centro caliente)
                {
                    position: 0,
                    start: { radius: 0.15, r: 1, g: 1, b: 0.95, a: 0.9 },
                    end: { radius: 0.5, a: 0 }
                },
                // Amarillo intenso brillante
                {
                    position: 0.12,
                    start: { radius: 0.25, r: 1, g: 0.95, b: 0.3, a: 0.85 },
                    end: { radius: 0.7, a: 0 }
                },
                // Amarillo-naranja brillante
                {
                    position: 0.28,
                    start: { radius: 0.2, r: 1, g: 0.75, b: 0.05, a: 0.75 },
                    middle: { radius: 0.5, r: 1, g: 0.55, b: 0, a: 0.7 },
                    end: { radius: 0.85, a: 0 }
                },
                // Naranja intenso
                {
                    position: 0.42,
                    start: { radius: 0.25, r: 1, g: 0.45, b: 0, a: 0.7 },
                    middle: { radius: 0.55, r: 1, g: 0.3, b: 0, a: 0.6 },
                    end: { radius: 0.9, a: 0 }
                },
                // Rojo-naranja vibrante
                {
                    position: 0.55,
                    start: { radius: 0.3, r: 1, g: 0.2, b: 0, a: 0.65 },
                    middle: { radius: 0.6, r: 0.95, g: 0.12, b: 0, a: 0.55 },
                    end: { radius: 1, a: 0 }
                },
                // Rojo intenso
                {
                    position: 0.68,
                    start: { radius: 0.25, r: 0.9, g: 0.08, b: 0, a: 0.55 },
                    middle: { radius: 0.6, r: 0.7, g: 0.05, b: 0, a: 0.45 },
                    end: { radius: 1, a: 0 }
                },
                // Rojo oscuro con inicio de humo
                {
                    position: 0.8,
                    start: { radius: 0.2, r: 0.5, g: 0.04, b: 0, a: 0.45 },
                    middle: { radius: 0.55, r: 0.3, g: 0.02, b: 0, a: 0.35 },
                    end: { radius: 1, a: 0 }
                },
                // Humo con restos de brasa
                {
                    position: 0.9,
                    start: { radius: 0.25, r: 0.2, g: 0.06, b: 0.02, a: 0.35 },
                    middle: { radius: 0.6, r: 0.12, g: 0.1, b: 0.08, a: 0.25 },
                    end: { radius: 1, a: 0 }
                },
                // Humo tenue final (se desvanece)
                {
                    position: 1,
                    start: { radius: 0.3, r: 0.08, g: 0.08, b: 0.08, a: 0.12 },
                    end: { radius: 1, a: 0 }
                }
            ];

            // Normalizar datos intermedios
            keyframes.forEach((k: any) => {
                if (!k.middle) {
                    k.middle = { ...k.start };
                    k.start.radius = 0;
                }
                ['r', 'g', 'b', 'a'].forEach(p => {
                    k.middle[p] = k.middle[p] ?? k.start[p];
                    k.end[p] = k.end[p] ?? k.middle[p];
                });
            });

            // Generar frames interpolados
            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame: any = keyframes[i - 1];
                const thisFrame: any = keyframes[i];
                const batchSize = Math.floor(
                    (thisFrame.position - lastFrame.position) * framesToGenerate
                );

                for (let j = 1; j <= batchSize; j++) {
                    const mult = j / batchSize;
                    const frame: any = {};

                    ['start', 'middle', 'end'].forEach(key => {
                        frame[key] = {};
                        ['radius', 'r', 'g', 'b', 'a'].forEach(prop => {
                            frame[key][prop] = interpolate(
                                lastFrame[key][prop] ?? 0,
                                thisFrame[key][prop] ?? 0,
                                mult
                            );
                        });
                    });

                    const sprite = createCachedSprite((spriteCtx, w, h) => {
                        const center = w / 2;
                        // Gradiente radial con centro ligeramente abajo
                        const grad = spriteCtx.createRadialGradient(
                            center, center * 1.15, 0,
                            center, center, center
                        );

                        grad.addColorStop(frame.start.radius, computeRGBA(frame.start));
                        if (frame.middle.radius > frame.start.radius) {
                            grad.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                        }
                        grad.addColorStop(frame.end.radius, computeRGBA(frame.end));

                        spriteCtx.fillStyle = grad;
                        spriteCtx.fillRect(0, 0, w, h);
                    });

                    state.flameGradientSprites.push(sprite);
                }
            }
        };

        // ============================================
        // SISTEMA DE PARTÍCULAS
        // ============================================
        const spawnParticle = () => {
            const angle = (config.direction - config.directionSpread / 2) * toRad;
            const spread = (config.directionSpread * toRad) / config.density;

            for (let i = 0; i < config.density; i++) {
                const subAngle = angle + (spread * i) + Math.random() * spread;
                const speedVariation = Math.random() * Math.random();
                const speed = config.velocity * (1 - speedVariation * config.velocitySpread);

                // Reciclar partícula del pool o crear nueva
                const p: Particle = state.gasPool.pop() || {
                    x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 0, size: 0
                };

                // Pequeña variación en el punto de spawn para más naturalidad
                const spawnOffsetX = (Math.random() - 0.5) * 20;

                p.x = config.spawnPoint.x + spawnOffsetX;
                p.y = config.spawnPoint.y;
                p.vx = Math.sin(subAngle) * speed;
                p.vy = -Math.cos(subAngle) * speed;
                p.age = 0;
                p.life = Math.random() * (config.lifespanMax - config.lifespanMin) + config.lifespanMin;
                p.size = config.gasRadius;

                state.gas.push(p);
            }
        };

        // ============================================
        // LOOP PRINCIPAL DE ANIMACIÓN
        // ============================================
        const tick = () => {
            const now = performance.now();
            const delta = now - state.lastTime;
            state.lastTime = now;

            // Cap en 60ms para evitar saltos grandes
            const simTime = Math.min(delta, 60);
            const simSpeed = simTime / 16.67;

            // Spawn de partículas
            state.spawnTimer += simTime;
            while (state.spawnTimer >= config.spawnDelay) {
                state.spawnTimer -= config.spawnDelay;
                spawnParticle();
            }

            // Física
            const damp = 1 - config.dampening * simSpeed;

            // Actualizar física de cada partícula
            for (let i = state.gas.length - 1; i >= 0; i--) {
                const p = state.gas[i];
                p.age += simTime;

                // Movimiento
                p.x += p.vx * simSpeed;
                p.y += p.vy * simSpeed;

                // Dampening y flotabilidad
                p.vx *= damp;
                p.vy = (p.vy * damp) + (config.gravity * simSpeed);

                // Eliminar partícula cuando expire
                if (p.age >= p.life || p.y < -p.size) {
                    state.gas.splice(i, 1);
                    state.gasPool.push(p);
                }
            }

            // ============================================
            // RENDERIZADO
            // ============================================
            ctx.clearRect(0, 0, config.width, config.height);

            // Modo 'screen' para que el fuego brille al superponerse
            ctx.globalCompositeOperation = 'screen';

            // Dibujar partículas de atrás hacia adelante
            for (let i = 0; i < state.gas.length; i++) {
                const p = state.gas[i];
                const progress = Math.min(1, p.age / p.life);
                const frameIdx = Math.floor(progress * (state.flameGradientSprites.length - 1));
                const sprite = state.flameGradientSprites[frameIdx];

                if (sprite) {
                    ctx.drawImage(sprite, p.x - p.size, p.y - p.size);
                }
            }

            ctx.globalCompositeOperation = 'source-over';

            animationFrameId = requestAnimationFrame(tick);
        };

        // Iniciar simulación
        generateFlameGradients();
        tick();

        // Cleanup al desmontar
        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, [spawnPosition, intensity]);

    return (
        <div
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className="relative flex items-end justify-center group cursor-pointer"
            style={{ width: '30vh', height: '60vh' }}
        >
            {/* CANVAS HUMO/FUEGO (Detrás de la imagen) */}
            <canvas
                ref={canvasRef}
                className="absolute left-1/2 bottom-0 transform -translate-x-1/2 pointer-events-none"
                style={{
                    width: '100%',
                    height: '120%',
                    zIndex: 0,
                    bottom: '-10%',
                    mixBlendMode: 'screen',
                    opacity: 0.95
                }}
            />

            {/* IMAGEN BARRIL (Delante) */}
            <img
                src="https://i.imgur.com/fr9Bz6G.png"
                alt="Barril Tóxico"
                className="relative z-10 w-full h-full object-contain object-bottom transition-all duration-300 group-hover:brightness-110"
                style={{
                    filter: 'drop-shadow(0 0 25px rgba(242, 208, 25, 0.25))'
                }}
                draggable="false"
            />

            {/* UI Label on Hover */}
            <div
                className="absolute top-[30%] left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-20 pointer-events-none"
            >
                <div className="bg-black/80 border border-[#F2D019] px-3 py-1 skew-x-[-15deg]">
                    <span className="block transform skew-x-[15deg] font-['Teko'] text-[#F2D019] text-xl tracking-widest leading-none">
                        CONTACTO
                    </span>
                </div>
                <div className="w-[1px] h-8 bg-[#F2D019] mx-auto opacity-50" />
            </div>
        </div>
    );
});

