import React, { useEffect, useRef } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface BarrelSmokeProps {
    onClick: () => void;
}

export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({ onClick }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Configuración de interacción
    const interactionProps = useImageInteraction("TOXIC BARREL: UPLINK", "https://i.imgur.com/fr9Bz6G.png");

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let animationFrameId: number;

        const config = {
            width: 300,
            height: 600,
            // Ajustado para que el humo salga de la parte superior del barril (boca)
            // height total 600, barril ocupa aprox 80%, boca está cerca de y=120
            spawnPoint: { x: 150, y: 140 }, 
            gasRadius: 45,                  // Radio un poco más pequeño para salir de la boca
            density: 5,                     // Menos densidad para ver el barril
            spawnDelay: 40,
            velocity: 2.2,                  // Más lento, más pesado (tóxico)
            velocitySpread: 0.5,
            direction: 0,
            directionSpread: 25             // Spread contenido (tipo chimenea)
        };

        const state = {
            gas: [] as any[],
            gasPool: [] as any[],
            flameGradientSprites: [] as HTMLCanvasElement[],
            lastTime: performance.now(),
            spawnTimer: 0
        };

        canvas.width = config.width;
        canvas.height = config.height;

        const toRad = Math.PI / 180;
        const interpolate = (start: number, end: number, pos: number) => (end - start) * pos + start;
        const computeRGBA = (c: any) => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;

        const createCachedSprite = (drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void) => {
            const c = document.createElement('canvas');
            const dim = config.gasRadius * 2;
            c.width = dim;
            c.height = dim;
            const cx = c.getContext('2d');
            if (cx) drawFn(cx, dim, dim);
            return c;
        };

        // --- GENERADOR TOXIC GREEN / YELLOW ---
        const generateFlameGradients = () => {
            const framesToGenerate = 120;

            // Keyframes ajustados a paleta TÓXICA (Verde/Amarillo/Negro)
            const keyframes = [
                // Núcleo blanco brillante
                { position: 0, start: { radius: 0.1, r: 1, g: 1, b: 1, a: 0.9 }, end: { radius: 0.4, a: 0 } },
                // Amarillo neón intenso (#F2D019 aprox)
                { position: 0.15, start: { radius: 0.2, r: 0.95, g: 0.82, b: 0.1, a: 0.8 }, end: { radius: 0.7, a: 0 } },
                // Verde tóxico brillante
                { position: 0.3, start: { radius: 0.15, r: 0.4, g: 0.9, b: 0.2, a: 0.7 }, middle: { radius: 0.4, r: 0.6, g: 0.8, b: 0.1, a: 0.6 }, end: { radius: 0.8, a: 0 } },
                // Verde oscuro/musgo
                { position: 0.5, start: { radius: 0.2, r: 0.2, g: 0.6, b: 0.1, a: 0.6 }, middle: { radius: 0.5, r: 0.1, g: 0.4, b: 0.05, a: 0.5 }, end: { radius: 0.9, a: 0 } },
                // Humo negro verdoso
                { position: 0.75, start: { radius: 0.2, r: 0.05, g: 0.15, b: 0.05, a: 0.5 }, middle: { radius: 0.6, r: 0.02, g: 0.05, b: 0.02, a: 0.4 }, end: { radius: 1, a: 0 } },
                // Desvanecimiento final
                { position: 1, start: { radius: 0.3, r: 0, g: 0, b: 0, a: 0.2 }, end: { radius: 1, a: 0 } }
            ];

            // Normalización
            keyframes.forEach((k: any) => {
                if (!k.middle) { k.middle = { ...k.start }; k.start.radius = 0; }
                ['r', 'g', 'b', 'a'].forEach(p => {
                    k.middle[p] = k.middle[p] ?? k.start[p];
                    k.end[p] = k.end[p] ?? k.middle[p];
                });
            });

            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame: any = keyframes[i - 1];
                const thisFrame: any = keyframes[i];
                const batchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= batchSize; j++) {
                    const mult = j / batchSize;
                    const frame: any = {};
                    ['start', 'middle', 'end'].forEach(key => {
                        frame[key] = {};
                        ['radius', 'r', 'g', 'b', 'a'].forEach(prop => {
                            frame[key][prop] = interpolate(lastFrame[key][prop] || 0, thisFrame[key][prop] || 0, mult);
                        });
                    });

                    const sprite = createCachedSprite((ctx, w, h) => {
                        const center = w / 2;
                        const grad = ctx.createRadialGradient(center, center, 0, center, center, center);
                        grad.addColorStop(frame.start.radius, computeRGBA(frame.start));
                        if(frame.middle.radius > frame.start.radius) grad.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                        grad.addColorStop(frame.end.radius, computeRGBA(frame.end));

                        ctx.fillStyle = grad;
                        ctx.fillRect(0, 0, w, h);
                    });

                    state.flameGradientSprites.push(sprite);
                }
            }
        };

        const spawnParticle = () => {
            const angle = (config.direction - config.directionSpread / 2) * toRad;
            const spread = (config.directionSpread * toRad) / config.density;

            for (let i = 0; i < config.density; i++) {
                const subAngle = angle + (spread * i) + Math.random() * spread;
                const speed = config.velocity * (1 - (1 - Math.random() * Math.random()) * config.velocitySpread);

                const p = state.gasPool.pop() || { x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 0, size: 0 };

                p.x = config.spawnPoint.x;
                p.y = config.spawnPoint.y;
                p.vx = Math.sin(subAngle) * speed;
                p.vy = -Math.cos(subAngle) * speed; // Hacia arriba
                p.age = 0;
                p.life = Math.random() * 1500 + 2000;
                p.size = config.gasRadius;
                state.gas.push(p);
            }
        };

        const tick = () => {
            const now = performance.now();
            const delta = now - state.lastTime;
            state.lastTime = now;

            const simTime = Math.min(delta, 60); 
            const simSpeed = simTime / 16.67;

            state.spawnTimer += simTime;
            while (state.spawnTimer >= config.spawnDelay) {
                state.spawnTimer -= config.spawnDelay;
                spawnParticle();
            }

            const damp = 1 - 0.01 * simSpeed;
            const lift = -0.05; // Flotabilidad hacia arriba

            for (let i = state.gas.length - 1; i >= 0; i--) {
                const p = state.gas[i];
                p.age += simTime;
                p.x += p.vx * simSpeed;
                p.y += p.vy * simSpeed;
                p.vx *= damp;
                p.vy = (p.vy * damp) + (lift * simSpeed);

                // Expansión gradual
                p.size += 0.1 * simSpeed;

                if (p.age >= p.life) {
                    state.gas.splice(i, 1);
                    state.gasPool.push(p);
                }
            }

            ctx.clearRect(0, 0, config.width, config.height);

            // Screen blending para brillo tóxico
            ctx.globalCompositeOperation = 'screen'; 

            for (let i = 0; i < state.gas.length; i++) {
                const p = state.gas[i];
                const life = Math.min(1, p.age / p.life);
                const spriteIndex = Math.floor(life * (state.flameGradientSprites.length - 1));
                const sprite = state.flameGradientSprites[spriteIndex];

                if (sprite) {
                    ctx.drawImage(sprite, p.x - p.size, p.y - p.size, p.size * 2, p.size * 2);
                }
            }

            // Volver a normal para otros renders si los hubiera
            ctx.globalCompositeOperation = 'source-over';

            animationFrameId = requestAnimationFrame(tick);
        };

        generateFlameGradients();
        tick();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative flex items-end justify-center group cursor-pointer ${interactionProps.className}`}
            style={{ width: '30vh', height: '60vh' }}
            onMouseEnter={interactionProps.onMouseEnter}
            onMouseLeave={interactionProps.onMouseLeave}
        >
            {/* CANVAS HUMO - Z-INDEX 20 (ENCIMA DEL BARRIL PARA QUE SALGA DE LA BOCA) */}
            <canvas 
                ref={canvasRef} 
                className="absolute left-1/2 bottom-0 transform -translate-x-1/2 pointer-events-none"
                style={{ width: '100%', height: '100%', zIndex: 20, mixBlendMode: 'screen', opacity: 0.9 }}
            />

            {/* IMAGEN BARRIL - Z-INDEX 10 */}
            <img 
                src="https://i.imgur.com/fr9Bz6G.png" 
                alt="Barril Tóxico" 
                className="relative z-10 w-full h-full object-contain object-bottom drop-shadow-[0_0_15px_rgba(0,255,0,0.2)] transition-all duration-300 group-hover:brightness-110"
                draggable="false"
            />

            {/* UI Label on Hover */}
            <div className="absolute top-[30%] left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-30 pointer-events-none">
                <div className="bg-black/90 border border-[#F2D019] px-4 py-1 skew-x-[-15deg] shadow-[0_0_15px_rgba(242,208,25,0.4)]">
                    <span className="block transform skew-x-[15deg] font-['Teko'] text-[#F2D019] text-2xl tracking-widest leading-none">CONTACTO</span>
                </div>
                <div className="w-[1px] h-8 bg-[#F2D019] mx-auto opacity-80" />
            </div>
        </div>
    );
});

import React, { useEffect, useRef } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface BarrelSmokeProps {
    onClick: () => void;
}

export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({ onClick }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Configuración de interacción
    const interactionProps = useImageInteraction("TOXIC BARREL: UPLINK", "https://i.imgur.com/fr9Bz6G.png");

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let animationFrameId: number;

        const config = {
            width: 300,
            height: 600,
            // CORRECCIÓN CRÍTICA: Bajamos el punto de spawn (y: 380) para que coincida 
            // con la boca física del barril en la imagen alineada al fondo.
            spawnPoint: { x: 150, y: 380 }, 
            gasRadius: 40,                  // Radio ajustado al hueco del barril
            density: 6,                     // Mayor densidad para parecer fuego líquido
            spawnDelay: 25,                 // Emisión más rápida
            velocity: 3.5,                  // Velocidad alta inicial (presión)
            velocitySpread: 0.4,
            direction: 0,
            directionSpread: 15             // Columna más cerrada al inicio
        };

        const state = {
            gas: [] as any[],
            gasPool: [] as any[],
            flameGradientSprites: [] as HTMLCanvasElement[],
            lastTime: performance.now(),
            spawnTimer: 0
        };

        canvas.width = config.width;
        canvas.height = config.height;

        const toRad = Math.PI / 180;
        const interpolate = (start: number, end: number, pos: number) => (end - start) * pos + start;
        const computeRGBA = (c: any) => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a})`;

        const createCachedSprite = (drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void) => {
            const c = document.createElement('canvas');
            const dim = config.gasRadius * 2.5; // Margen extra para el glow
            c.width = dim;
            c.height = dim;
            const cx = c.getContext('2d');
            if (cx) drawFn(cx, dim, dim);
            return c;
        };

        // --- GENERADOR DE FUEGO RADIACTIVO ---
        const generateFlameGradients = () => {
            const framesToGenerate = 120;

            const keyframes = [
                // 0%: Núcleo blanco caliente (Salida)
                { position: 0, start: { radius: 0.1, r: 1, g: 1, b: 1, a: 1 }, end: { radius: 0.3, a: 0 } },

                // 20%: Amarillo Neón Intenso (Ignición)
                { position: 0.2, start: { radius: 0.15, r: 1, g: 0.9, b: 0.2, a: 0.9 }, end: { radius: 0.5, a: 0 } },

                // 50%: Verde Tóxico (Cuerpo principal)
                { position: 0.5, start: { radius: 0.2, r: 0.4, g: 1, b: 0.1, a: 0.7 }, middle: { radius: 0.5, r: 0.2, g: 0.8, b: 0.1, a: 0.5 }, end: { radius: 0.8, a: 0 } },

                // 80%: Humo Oscuro Verdoso (Disipación)
                { position: 0.8, start: { radius: 0.25, r: 0.1, g: 0.3, b: 0.1, a: 0.4 }, middle: { radius: 0.6, r: 0.05, g: 0.1, b: 0.05, a: 0.3 }, end: { radius: 1, a: 0 } },

                // 100%: Transparente
                { position: 1, start: { radius: 0.3, r: 0, g: 0, b: 0, a: 0 }, end: { radius: 1.2, a: 0 } }
            ];

            // Normalización
            keyframes.forEach((k: any) => {
                if (!k.middle) { k.middle = { ...k.start }; k.start.radius = 0; }
                ['r', 'g', 'b', 'a'].forEach(p => {
                    k.middle[p] = k.middle[p] ?? k.start[p];
                    k.end[p] = k.end[p] ?? k.middle[p];
                });
            });

            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame: any = keyframes[i - 1];
                const thisFrame: any = keyframes[i];
                const batchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= batchSize; j++) {
                    const mult = j / batchSize;
                    const frame: any = {};
                    ['start', 'middle', 'end'].forEach(key => {
                        frame[key] = {};
                        ['radius', 'r', 'g', 'b', 'a'].forEach(prop => {
                            frame[key][prop] = interpolate(lastFrame[key][prop] || 0, thisFrame[key][prop] || 0, mult);
                        });
                    });

                    const sprite = createCachedSprite((ctx, w, h) => {
                        const center = w / 2;
                        const grad = ctx.createRadialGradient(center, center, 0, center, center, center);
                        grad.addColorStop(frame.start.radius, computeRGBA(frame.start));
                        if(frame.middle.radius > frame.start.radius) grad.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                        grad.addColorStop(frame.end.radius, computeRGBA(frame.end));

                        ctx.fillStyle = grad;
                        ctx.fillRect(0, 0, w, h);
                    });

                    state.flameGradientSprites.push(sprite);
                }
            }
        };

        const spawnParticle = () => {
            const angle = (config.direction - config.directionSpread / 2) * toRad;
            const spread = (config.directionSpread * toRad) / config.density;

            for (let i = 0; i < config.density; i++) {
                const subAngle = angle + (spread * i) + (Math.random() - 0.5) * spread;
                const speed = config.velocity * (0.8 + Math.random() * 0.4);

                const p = state.gasPool.pop() || { x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 0, size: 0, rotation: 0, rotSpeed: 0 };

                // Spawn en elipse para simular la boca del barril en perspectiva
                const r = Math.random() * config.gasRadius;
                const theta = Math.random() * Math.PI * 2;

                p.x = config.spawnPoint.x + r * Math.cos(theta);
                p.y = config.spawnPoint.y + (r * 0.4) * Math.sin(theta); // Aplastado en Y por perspectiva

                p.vx = Math.sin(subAngle) * speed * 0.5; // Menos dispersión lateral
                p.vy = -Math.cos(subAngle) * speed; // Fuerte hacia arriba
                p.age = 0;
                p.life = Math.random() * 1000 + 1500;
                p.size = config.gasRadius * (0.5 + Math.random() * 0.5);
                p.rotation = Math.random() * Math.PI * 2;
                p.rotSpeed = (Math.random() - 0.5) * 0.05;

                state.gas.push(p);
            }
        };

        const tick = () => {
            const now = performance.now();
            const delta = now - state.lastTime;
            state.lastTime = now;

            const simTime = Math.min(delta, 50); 
            const simSpeed = simTime / 16.67;

            state.spawnTimer += simTime;
            while (state.spawnTimer >= config.spawnDelay) {
                state.spawnTimer -= config.spawnDelay;
                spawnParticle();
            }

            const damp = 0.98; // Resistencia del aire
            const lift = -0.02; // Flotabilidad adicional

            for (let i = state.gas.length - 1; i >= 0; i--) {
                const p = state.gas[i];
                p.age += simTime;

                // Física
                p.x += p.vx * simSpeed;
                p.y += p.vy * simSpeed;
                p.vx *= damp;
                p.vy = (p.vy * damp) + (lift * simSpeed);
                p.rotation += p.rotSpeed * simSpeed;

                // Crecimiento del humo al subir
                p.size += 0.25 * simSpeed;

                if (p.age >= p.life) {
                    state.gas.splice(i, 1);
                    state.gasPool.push(p);
                }
            }

            ctx.clearRect(0, 0, config.width, config.height);

            // Render Pass 1: Additive blending for CORE (Glow)
            ctx.globalCompositeOperation = 'lighter';

            for (let i = 0; i < state.gas.length; i++) {
                const p = state.gas[i];
                const lifeProgress = p.age / p.life;

                // Solo partículas jóvenes y calientes usan 'lighter'
                if (lifeProgress < 0.5) {
                    const spriteIndex = Math.floor(lifeProgress * (state.flameGradientSprites.length - 1));
                    const sprite = state.flameGradientSprites[spriteIndex];
                    if (sprite) {
                        ctx.save();
                        ctx.translate(p.x, p.y);
                        // ctx.rotate(p.rotation); // Rotación opcional, costosa
                        ctx.drawImage(sprite, -p.size, -p.size, p.size * 2, p.size * 2);
                        ctx.restore();
                    }
                }
            }

            // Render Pass 2: Source-Over for SMOKE (Darker/Opaque)
            ctx.globalCompositeOperation = 'source-over'; // Normal blending for smoke

            for (let i = 0; i < state.gas.length; i++) {
                const p = state.gas[i];
                const lifeProgress = p.age / p.life;

                // Partículas viejas (humo)
                if (lifeProgress >= 0.5) {
                    const spriteIndex = Math.floor(lifeProgress * (state.flameGradientSprites.length - 1));
                    const sprite = state.flameGradientSprites[spriteIndex];
                    if (sprite) {
                        ctx.save();
                        ctx.translate(p.x, p.y);
                        ctx.drawImage(sprite, -p.size, -p.size, p.size * 2, p.size * 2);
                        ctx.restore();
                    }
                }
            }

            animationFrameId = requestAnimationFrame(tick);
        };

        generateFlameGradients();
        tick();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative flex items-end justify-center group cursor-pointer ${interactionProps.className}`}
            style={{ width: '30vh', height: '60vh' }}
            onMouseEnter={interactionProps.onMouseEnter}
            onMouseLeave={interactionProps.onMouseLeave}
        >
            {/* CANVAS HUMO - Z-INDEX 20 (Para que el fuego salga 'dentro' pero se vea por encima del borde trasero) */}
            <canvas 
                ref={canvasRef} 
                className="absolute left-1/2 bottom-0 transform -translate-x-1/2 pointer-events-none"
                style={{ width: '100%', height: '100%', zIndex: 15 }}
            />

            {/* IMAGEN BARRIL - Z-INDEX 10 */}
            <img 
                src="https://i.imgur.com/fr9Bz6G.png" 
                alt="Barril Tóxico" 
                className="relative z-10 w-full h-full object-contain object-bottom drop-shadow-[0_0_15px_rgba(0,255,0,0.1)] transition-all duration-300 group-hover:brightness-110"
                draggable="false"
            />

            {/* UI Label on Hover */}
            <div className="absolute top-[20%] left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-30 pointer-events-none">
                <div className="bg-black/90 border border-[#F2D019] px-4 py-1 skew-x-[-15deg] shadow-[0_0_15px_rgba(242,208,25,0.4)]">
                    <span className="block transform skew-x-[15deg] font-['Teko'] text-[#F2D019] text-2xl tracking-widest leading-none">CONTACTO</span>
                </div>
                <div className="w-[1px] h-12 bg-[#F2D019] mx-auto opacity-80" />
            </div>
        </div>
    );
});

