                    /* Inset mayor para dar margen de seguridad al contenido */
                    --card-inset: 2px;
                    --portal-clip: polygon(10% 0, 90% 0, 100% 10%, 100% 90%, 90% 100%, 10% 100%, 0 90%, 0 10%);
                    --transition-snappy: cubic-bezier(0.25, 0.46, 0.45, 0.94);
