import React, { useEffect, useRef } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface BarrelSmokeProps {
    onClick: () => void;
}

export const BarrelSmoke: React.FC<BarrelSmokeProps> = React.memo(({ onClick }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    const interactionProps = useImageInteraction("TOXIC BARREL: UPLINK", "https://i.imgur.com/fr9Bz6G.png");

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let animationFrameId: number;

        const config = {
            width: 300,
            height: 600,
            // Ajustado spawnPoint para mejor alineación visual dentro del borde del barril
            spawnPoint: { x: 150, y: 390 }, 
            gasRadius: 35,
            density: 6,
            spawnDelay: 25,
            velocity: 3.5,
            velocitySpread: 0.4,
            direction: 0,
            directionSpread: 15
        };

        const state = {
            gas: [] as any[],
            gasPool: [] as any[],
            flameGradientSprites: [] as HTMLCanvasElement[],
            lastTime: performance.now(),
            spawnTimer: 0
        };

        canvas.width = config.width;
        canvas.height = config.height;

        const toRad = Math.PI / 180;
        const interpolate = (start: number, end: number, pos: number) => (end - start) * pos + start;
        const computeRGBA = (c: any) => `rgba(${c.r * 255 | 0},${c.g * 255 | 0},${c.b * 255 | 0},${c.a ?? 1})`;

        const createCachedSprite = (drawFn: (ctx: CanvasRenderingContext2D, w: number, h: number) => void) => {
            const c = document.createElement('canvas');
            const dim = Math.floor(config.gasRadius * 2.5); 
            c.width = dim;
            c.height = dim;
            const cx = c.getContext('2d');
            if (cx) drawFn(cx, dim, dim);
            return c;
        };

        const generateFlameGradients = () => {
            const framesToGenerate = 120;

            const keyframes: any[] = [
                // Ajustado colores para mezclar mejor con el verde del barril
                { position: 0, start: { radius: 0.1, r: 0.9, g: 1, b: 0.9, a: 1 }, end: { radius: 0.3, a: 0 } },
                { position: 0.2, start: { radius: 0.15, r: 0.7, g: 1, b: 0.2, a: 0.9 }, end: { radius: 0.5, a: 0 } },
                { position: 0.5, start: { radius: 0.2, r: 0.3, g: 0.9, b: 0.1, a: 0.7 }, middle: { radius: 0.5, r: 0.1, g: 0.7, b: 0.1, a: 0.5 }, end: { radius: 0.8, a: 0 } },
                { position: 0.8, start: { radius: 0.25, r: 0.1, g: 0.4, b: 0.1, a: 0.4 }, middle: { radius: 0.6, r: 0.05, g: 0.2, b: 0.05, a: 0.3 }, end: { radius: 1, a: 0 } },
                { position: 1, start: { radius: 0.3, r: 0, g: 0, b: 0, a: 0 }, end: { radius: 1.2, a: 0 } }
            ];

            keyframes.forEach((k) => {
                if (!k.middle) { 
                    k.middle = { ...k.start }; 
                    k.start.radius = k.start.radius || 0.1; 
                }
                const props = ['radius', 'r', 'g', 'b', 'a'];
                props.forEach(p => {
                    k.middle[p] = k.middle[p] ?? k.start[p] ?? 0;
                    k.end[p] = k.end[p] ?? k.middle[p] ?? 0;
                });
            });

            for (let i = 1; i < keyframes.length; i++) {
                const lastFrame = keyframes[i - 1];
                const thisFrame = keyframes[i];
                const batchSize = Math.floor((thisFrame.position - lastFrame.position) * framesToGenerate);

                for (let j = 1; j <= batchSize; j++) {
                    const mult = j / batchSize;
                    const frame: any = {};
                    ['start', 'middle', 'end'].forEach(key => {
                        frame[key] = {};
                        ['radius', 'r', 'g', 'b', 'a'].forEach(prop => {
                            frame[key][prop] = interpolate(lastFrame[key][prop] || 0, thisFrame[key][prop] || 0, mult);
                        });
                    });

                    const sprite = createCachedSprite((ctx, w, h) => {
                        const center = w / 2;
                        const r1 = Math.max(0, frame.start.radius * (w/2));
                        const r2 = Math.max(0, frame.middle.radius * (w/2));
                        const r3 = Math.max(0, frame.end.radius * (w/2));

                        try {
                            const grad = ctx.createRadialGradient(center, center, 0, center, center, center);
                            grad.addColorStop(frame.start.radius, computeRGBA(frame.start));
                            if (frame.middle.radius > frame.start.radius) {
                                grad.addColorStop(frame.middle.radius, computeRGBA(frame.middle));
                            }
                            grad.addColorStop(frame.end.radius, computeRGBA(frame.end));

                            ctx.fillStyle = grad;
                            ctx.fillRect(0, 0, w, h);
                        } catch (e) {
                            // Silent fail
                        }
                    });

                    state.flameGradientSprites.push(sprite);
                }
            }
        };

        const spawnParticle = () => {
            const angle = (config.direction - config.directionSpread / 2) * toRad;
            const spread = (config.directionSpread * toRad) / config.density;

            for (let i = 0; i < config.density; i++) {
                const subAngle = angle + (spread * i) + (Math.random() - 0.5) * spread;
                const speed = config.velocity * (0.8 + Math.random() * 0.4);

                const p = state.gasPool.pop() || { x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 0, size: 0, rotation: 0, rotSpeed: 0 };

                const r = Math.random() * config.gasRadius;
                const theta = Math.random() * Math.PI * 2;

                p.x = config.spawnPoint.x + r * Math.cos(theta);
                p.y = config.spawnPoint.y + (r * 0.4) * Math.sin(theta);

                p.vx = Math.sin(subAngle) * speed * 0.5;
                p.vy = -Math.cos(subAngle) * speed;
                p.age = 0;
                p.life = Math.random() * 1000 + 1500;
                p.size = config.gasRadius * (0.5 + Math.random() * 0.5);
                p.rotation = Math.random() * Math.PI * 2;
                p.rotSpeed = (Math.random() - 0.5) * 0.05;

                state.gas.push(p);
            }
        };

        const tick = () => {
            const now = performance.now();
            const delta = now - state.lastTime;
            state.lastTime = now;

            const simTime = Math.min(delta, 50); 
            const simSpeed = simTime / 16.67;

            state.spawnTimer += simTime;
            while (state.spawnTimer >= config.spawnDelay) {
                state.spawnTimer -= config.spawnDelay;
                spawnParticle();
            }

            const damp = 0.98;
            const lift = -0.02;

            for (let i = state.gas.length - 1; i >= 0; i--) {
                const p = state.gas[i];
                p.age += simTime;

                p.x += p.vx * simSpeed;
                p.y += p.vy * simSpeed;
                p.vx *= damp;
                p.vy = (p.vy * damp) + (lift * simSpeed);
                p.rotation += p.rotSpeed * simSpeed;
                p.size += 0.25 * simSpeed;

                if (p.age >= p.life) {
                    state.gas.splice(i, 1);
                    state.gasPool.push(p);
                }
            }

            ctx.clearRect(0, 0, config.width, config.height);

            if (state.flameGradientSprites.length > 0) {
                ctx.globalCompositeOperation = 'lighter';

                for (let i = 0; i < state.gas.length; i++) {
                    const p = state.gas[i];
                    const lifeProgress = p.age / p.life;

                    if (lifeProgress < 0.5) {
                        const spriteIndex = Math.floor(lifeProgress * (state.flameGradientSprites.length - 1));
                        const sprite = state.flameGradientSprites[spriteIndex];
                        if (sprite) {
                            ctx.save();
                            ctx.translate(p.x, p.y);
                            ctx.drawImage(sprite, -p.size, -p.size, p.size * 2, p.size * 2);
                            ctx.restore();
                        }
                    }
                }

                ctx.globalCompositeOperation = 'source-over';

                for (let i = 0; i < state.gas.length; i++) {
                    const p = state.gas[i];
                    const lifeProgress = p.age / p.life;

                    if (lifeProgress >= 0.5) {
                        const spriteIndex = Math.floor(lifeProgress * (state.flameGradientSprites.length - 1));
                        const sprite = state.flameGradientSprites[spriteIndex];
                        if (sprite) {
                            ctx.save();
                            ctx.translate(p.x, p.y);
                            ctx.drawImage(sprite, -p.size, -p.size, p.size * 2, p.size * 2);
                            ctx.restore();
                        }
                    }
                }
            }

            animationFrameId = requestAnimationFrame(tick);
        };

        try {
            generateFlameGradients();
            tick();
        } catch (e) {
            console.error("BarrelSmoke error:", e);
        }

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div 
            ref={containerRef}
            onClick={(e) => { e.stopPropagation(); onClick(); }}
            className={`relative flex items-end justify-center group cursor-pointer ${interactionProps.className}`}
            style={{ width: '30vh', height: '60vh' }}
            onMouseEnter={interactionProps.onMouseEnter}
            onMouseLeave={interactionProps.onMouseLeave}
        >
            <canvas 
                ref={canvasRef} 
                className="absolute left-1/2 bottom-0 transform -translate-x-1/2 pointer-events-none"
                style={{ width: '100%', height: '100%', zIndex: 15 }}
            />

            <img 
                src="https://i.imgur.com/fr9Bz6G.png" 
                alt="Barril Tóxico" 
                className="relative z-10 w-full h-full object-contain object-bottom drop-shadow-[0_0_15px_rgba(0,255,0,0.1)] transition-all duration-300 group-hover:brightness-110"
                draggable="false"
            />

            <div className="absolute top-[20%] left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-30 pointer-events-none">
                <div className="bg-black/90 border border-[#F2D019] px-4 py-1 skew-x-[-15deg] shadow-[0_0_15px_rgba(242,208,25,0.4)]">
                    <span className="block transform skew-x-[15deg] font-['Teko'] text-[#F2D019] text-2xl tracking-widest leading-none">CONTACTO</span>
                </div>
                <div className="w-[1px] h-12 bg-[#F2D019] mx-auto opacity-80" />
            </div>
        </div>
    );
});

